import { Q, W, indexBy } from './_helper.js';

const M = (n, title, qs, opts) => W('S9TA', 'tieng-anh', n, title, qs, opts);

export const S9TA_WEEKS = [
  // ──────────────── HK1 ────────────────
  M(1, 'Local Environment — Crafts and traditional villages', [
    Q('Từ "craft" có nghĩa?', ['Nghệ thuật thủ công', 'Văn hóa', 'Cây cối', 'Máy móc'], 0, '"Craft" = nghề thủ công, sản phẩm thủ công.', ['Đúng — "craft" là nghề/sản phẩm thủ công làm bằng tay (vd traditional crafts).', 'Sai — "văn hóa" là "culture", nghĩa rộng hơn "craft".', 'Sai — "cây cối" là "trees/plants", không liên quan tới nghề thủ công.', 'Sai — "máy móc" là "machines/machinery", trái với thủ công.']),
    Q('"Artisan" nghĩa là?', ['Họa sĩ', 'Nhà điêu khắc', 'Người làm vườn', 'Nghệ nhân, thợ thủ công lành nghề'], 3, '"Artisan" = nghệ nhân thủ công.', ['Sai — "họa sĩ" là "painter/artist", khác với thợ thủ công.', 'Sai — "nhà điêu khắc" là "sculptor", chỉ một nghề hẹp.', 'Sai — "người làm vườn" là "gardener", không phải nghề thủ công.', 'Đúng — "artisan" là nghệ nhân/thợ thủ công lành nghề làm sản phẩm bằng tay.']),
    Q('Chọn từ phù hợp: Bat Trang is famous for its _____.', ['paintings', 'pottery', 'silk (lụa - làng Vạn Phúc)', 'bronze casting (đúc đồng - làng Đại Bái)'], 1, 'Bát Tràng nổi tiếng về gốm (pottery).', ['Sai — "paintings" (tranh) không phải đặc sản của Bát Tràng.', 'Đúng — Bát Tràng nổi tiếng làng gốm (pottery).', 'Sai — "silk" (lụa) là của làng Vạn Phúc, không phải Bát Tràng.', 'Sai — "bronze casting" (đúc đồng) là của làng Đại Bái.']),
    Q('"Handicraft" có nghĩa?', ['Đồ chơi', 'Đồ điện tử', 'Đồ ăn nhanh', 'Đồ thủ công'], 3, '"Handicraft" = sản phẩm thủ công làm bằng tay.', ['Sai — "đồ chơi" là "toy", không phải nghĩa của "handicraft".', 'Sai — "đồ điện tử" là "electronics", trái với làm bằng tay.', 'Sai — "đồ ăn nhanh" là "fast food", không liên quan.', 'Đúng — "handicraft" = sản phẩm thủ công làm bằng tay (hand + craft).']),
    Q('Chọn dạng đúng: He used to _____ a lot when he was young.', ['travels', 'travelling', 'travel', 'travelled'], 2, 'Sau "used to" dùng V nguyên thể.', ['Sai — "travels" chia ngôi thứ ba, nhưng sau "used to" phải là V nguyên thể.', 'Sai — "travelling" (V-ing) không dùng sau "used to + V".', 'Đúng — "used to + V nguyên thể" diễn tả thói quen quá khứ: used to travel.', 'Sai — "travelled" (V-ed) không đi sau "used to"; chỉ dùng V nguyên thể.']),
    Q('"Weave" có nghĩa?', ['Đan (dùng cho "knit/braid")', 'Dệt', 'Nhuộm (dùng cho "dye")', 'Thêu (dùng cho "embroider")'], 1, '"Weave" = dệt (vải, chiếu…).', ['Sai — "đan" là "knit/braid", thao tác khác với dệt.', 'Đúng — "weave" = dệt (vải, chiếu, thảm).', 'Sai — "nhuộm" là "dye", không phải "weave".', 'Sai — "thêu" là "embroider", khác với dệt.']),
  ]),

  M(2, 'Local Environment — Grammar: Phrasal verbs, complex sentences', [
    Q('"Look after" nghĩa là?', ['Bỏ qua', 'Chăm sóc', 'Tìm kiếm', 'Nhìn lên'], 1, '"Look after" = take care of = chăm sóc.', ['Sai — "bỏ qua" gần với "look over/ignore", không phải "look after".', 'Đúng — "look after" = take care of = chăm sóc.', 'Sai — "tìm kiếm" là "look for", một phrasal verb khác.', 'Sai — "nhìn lên" là nghĩa đen "look up", không phải "look after".']),
    Q('"Turn down" nghĩa là?', ['Tăng tốc', 'Bật lên', 'Từ chối / vặn nhỏ', 'Quay lại'], 2, '"Turn down" = từ chối hoặc giảm âm lượng.', ['Sai — "tăng tốc" là "speed up", không phải "turn down".', 'Sai — "bật lên/vặn to" là "turn up", trái nghĩa với "turn down".', 'Đúng — "turn down" = từ chối (lời mời) hoặc vặn nhỏ âm lượng.', 'Sai — "quay lại" là "turn back/return", không phải "turn down".']),
    Q('Chọn liên từ phù hợp: She was tired _____ she still finished the work.', ['so (vì vậy - chỉ kết quả, không hợp ngữ cảnh)', 'because', 'although', 'and (và - nối đẳng lập, không thể hiện tương phản)'], 2, '"Although" diễn tả sự nhượng bộ: mặc dù mệt nhưng vẫn làm xong.', ['Sai — "so" chỉ kết quả, không diễn tả sự tương phản giữa hai vế.', 'Sai — "because" chỉ nguyên nhân, không hợp với ý "mệt nhưng vẫn làm".', 'Đúng — "although" = mặc dù, diễn tả nhượng bộ/tương phản.', 'Sai — "and" chỉ nối đẳng lập, không thể hiện sự đối lập.']),
    Q('Câu phức nào đúng?', ['Because it was raining, we stayed home.', 'Because of it was raining, we stayed home.', 'Because for it was raining, we stayed home.', 'Because it was raining, so we stayed home.'], 0, 'Cấu trúc: Because + S + V, S + V (không thêm "so").', ['Đúng — "Because + S + V, S + V" là cấu trúc câu phức chuẩn.', 'Sai — "because of" phải theo sau là danh từ/V-ing, không theo mệnh đề.', 'Sai — "because for" không tồn tại; "because" đã đủ nghĩa.', 'Sai — không dùng cả "because" và "so" trong cùng một câu.']),
    Q('"Set up" có nghĩa?', ['Đứng dậy', 'Mua sắm', 'Sửa chữa', 'Thành lập, thiết lập'], 3, '"Set up a business" = thành lập doanh nghiệp.', ['Sai — "đứng dậy" là "stand up", không phải "set up".', 'Sai — "mua sắm" là "go shopping", không liên quan.', 'Sai — "sửa chữa" là "fix/repair", khác với "set up".', 'Đúng — "set up" = thành lập, thiết lập (set up a business).']),
    Q('"Look forward to" được theo sau bởi?', ['V-ing (chỉ đúng khi không có "to" đi liền)', 'To + V', 'Danh từ hoặc V-ing', 'V nguyên thể'], 2, '"Look forward to" + noun/gerund (V-ing).', ['Sai — đáp án này thiếu trường hợp danh từ; "to" ở đây là giới từ nên theo sau là noun/V-ing.', 'Sai — "to" trong cụm này là giới từ, không phải "to" của "to + V".', 'Đúng — "look forward to" + noun hoặc V-ing (vd looking forward to seeing you).', 'Sai — không dùng V nguyên thể vì "to" là giới từ.']),
  ]),

  M(3, 'City Life — Vocabulary about urban life', [
    Q('"Urban" có nghĩa?', ['Cổ kính', 'Hiện đại', 'Thuộc nông thôn', 'Thuộc thành thị'], 3, '"Urban" = thuộc về thành phố; "rural" = nông thôn.', ['Sai — "cổ kính" là "ancient", không phải nghĩa của "urban".', 'Sai — "hiện đại" là "modern"; "urban" nói về thành thị chứ không phải mức độ hiện đại.', 'Sai — "thuộc nông thôn" là "rural", trái nghĩa với "urban".', 'Đúng — "urban" = thuộc thành thị; trái nghĩa là "rural" (nông thôn).']),
    Q('"Skyscraper" là?', ['Bầu trời', 'Tòa nhà chọc trời', 'Cầu vượt', 'Máy bay'], 1, '"Skyscraper" = tòa nhà cao tầng.', ['Sai — "bầu trời" là "sky"; "skyscraper" là từ ghép có nghĩa khác.', 'Đúng — "skyscraper" = tòa nhà chọc trời (sky + scrape).', 'Sai — "cầu vượt" là "overpass/flyover", không phải "skyscraper".', 'Sai — "máy bay" là "airplane", không liên quan.']),
    Q('"Traffic jam" nghĩa là?', ['Đèn giao thông', 'Bãi đậu xe', 'Cảnh sát giao thông', 'Tắc đường'], 3, '"Traffic jam" = ùn tắc giao thông.', ['Sai — "đèn giao thông" là "traffic lights", không phải "jam".', 'Sai — "bãi đậu xe" là "car park/parking lot".', 'Sai — "cảnh sát giao thông" là "traffic police".', 'Đúng — "traffic jam" = tắc đường, ùn tắc giao thông.']),
    Q('"Crowded" có nghĩa?', ['Yên tĩnh', 'Vắng vẻ', 'Đông đúc', 'Rộng rãi'], 2, '"Crowded" = đông người, chen chúc.', ['Sai — "yên tĩnh" là "quiet", không phải "crowded".', 'Sai — "vắng vẻ" là "deserted/empty", trái nghĩa với "crowded".', 'Đúng — "crowded" = đông đúc, chen chúc.', 'Sai — "rộng rãi" là "spacious", không liên quan tới mật độ người.']),
    Q('Chọn cụm từ phù hợp: Big cities offer many _____.', ['opportunity', 'opportunitys', 'opportunites', 'opportunities'], 3, '"Opportunities" — số nhiều của "opportunity".', ['Sai — "opportunity" là số ít, nhưng "many" cần danh từ số nhiều.', 'Sai — "opportunitys" sai chính tả; danh từ tận cùng "-y" sau phụ âm đổi thành "-ies".', 'Sai — "opportunites" thiếu chữ "i", sai chính tả.', 'Đúng — "opportunities" là dạng số nhiều đúng (y → ies) sau "many".']),
    Q('"Cost of living" nghĩa là?', ['Tiền nhà', 'Giá hàng', 'Lương tháng', 'Chi phí sinh hoạt'], 3, '"Cost of living" = chi phí sinh hoạt nói chung.', ['Sai — "tiền nhà" là "rent", chỉ một phần của chi phí sinh hoạt.', 'Sai — "giá hàng" là "price of goods", hẹp hơn "cost of living".', 'Sai — "lương tháng" là "monthly salary", không phải chi phí.', 'Đúng — "cost of living" = chi phí sinh hoạt nói chung.']),
  ]),

  M(4, 'City Life — Comparative & Superlative + Phrasal verbs', [
    Q('Chọn dạng đúng: Ho Chi Minh City is _____ than Hanoi.', ['bigger', 'biggest', 'more big', 'big (nguyên cấp - thiếu "-er" so sánh hơn)'], 0, 'So sánh hơn của tính từ ngắn: bigger.', ['Đúng — tính từ ngắn "big" so sánh hơn thêm "-er" (gấp đôi g): bigger than.', 'Sai — "biggest" là so sánh nhất, dùng với "the", không đi với "than".', 'Sai — không dùng "more" với tính từ ngắn; phải là "bigger".', 'Sai — "big" là nguyên cấp, thiếu "-er" của so sánh hơn.']),
    Q('Chọn dạng đúng: London is one of the _____ cities in the world.', ['expensive', 'expensiver', 'most expensive', 'more expensive'], 2, 'So sánh hơn nhất của tính từ dài: the most expensive.', ['Sai — "expensive" nguyên cấp, nhưng "one of the ___ cities" cần so sánh nhất.', 'Sai — "expensiver" sai; tính từ dài không thêm "-er".', 'Đúng — "one of the most expensive" là so sánh nhất của tính từ dài.', 'Sai — "more expensive" là so sánh hơn, không hợp với "one of the ___".']),
    Q('"As + adj + as" diễn tả?', ['So sánh kép', 'So sánh bằng', 'So sánh hơn', 'So sánh nhất'], 1, 'Cấu trúc "as ... as" = so sánh bằng.', ['Sai — so sánh kép là "the + comparative, the + comparative".', 'Đúng — "as + adj + as" diễn tả so sánh bằng (ngang nhau).', 'Sai — so sánh hơn dùng "-er/more ... than", không dùng "as ... as".', 'Sai — so sánh nhất dùng "the + -est/most".']),
    Q('Hoàn thành: Tokyo is _____ as Seoul.', ['more crowded', 'as crowded', 'most crowded', 'as crowdedly'], 1, 'Cấu trúc "as + adj + as".', ['Sai — "more crowded" là so sánh hơn, phải đi với "than", không với "as".', 'Đúng — "as crowded as" là cấu trúc so sánh bằng (as + adj + as).', 'Sai — "most crowded" là so sánh nhất, không đi với "as".', 'Sai — "crowdedly" là trạng từ; trong "as ... as" cần tính từ "crowded".']),
    Q('"Get on with" nghĩa là?', ['Hòa hợp với ai đó', 'Cả 3 đáp án', 'Lên xe', 'Tiến hành'], 1, '"Get on with sb" = hòa hợp; "get on with sth" = tiến hành; "get on the bus" = lên xe.', ['Sai — đây chỉ là một nghĩa; "get on" còn có nghĩa "tiến hành" và "lên xe".', 'Đúng — "get on" mang cả ba nghĩa tùy ngữ cảnh: hòa hợp, tiến hành, lên xe.', 'Sai — "lên xe" (get on the bus) chỉ là một nghĩa trong số đó.', 'Sai — "tiến hành" (get on with sth) chỉ là một nghĩa trong số đó.']),
    Q('Chọn từ đúng: I find city life much _____ than country life.', ['exciting', 'excited', 'most exciting', 'more exciting'], 3, 'Sau "much" + so sánh hơn: "more exciting".', ['Sai — "exciting" nguyên cấp, nhưng có "than" nên cần so sánh hơn.', 'Sai — "excited" tả cảm xúc người; ở đây tả sự vật nên dùng "-ing".', 'Sai — "most exciting" là so sánh nhất, không đi với "than".', 'Đúng — "much more exciting than" — "much" nhấn mạnh so sánh hơn của tính từ dài.']),
  ]),

  M(5, 'Teen Stress and Pressure — Vocabulary', [
    Q('"Stress" có nghĩa?', ['Áp lực, căng thẳng', 'Niềm vui', 'Sự tự tin', 'Thành công'], 0, '"Stress" = căng thẳng.', ['Đúng — "stress" = sự căng thẳng, áp lực tâm lý.', 'Sai — "niềm vui" là "joy", trái với "stress".', 'Sai — "sự tự tin" là "confidence", không phải "stress".', 'Sai — "thành công" là "success", không liên quan.']),
    Q('"Pressure" nghĩa là?', ['Hạnh phúc', 'Sức ép, áp lực', 'Sức khỏe', 'Sự thư giãn (relaxation - trái nghĩa)'], 1, '"Pressure" = áp lực.', ['Sai — "hạnh phúc" là "happiness", không phải "pressure".', 'Đúng — "pressure" = sức ép, áp lực (peer pressure, exam pressure).', 'Sai — "sức khỏe" là "health", không liên quan.', 'Sai — "sự thư giãn" là "relaxation", trái nghĩa với áp lực.']),
    Q('"Cope with" có nghĩa?', ['Yêu thương', 'Đối phó với, xử lý', 'Tránh xa', 'Học tập'], 1, '"Cope with stress" = đối phó với căng thẳng.', ['Sai — "yêu thương" là "love", không phải "cope with".', 'Đúng — "cope with" = đối phó/xử lý (vd cope with stress).', 'Sai — "tránh xa" là "avoid/stay away from", khác với đối phó.', 'Sai — "học tập" là "study", không liên quan tới nghĩa "cope".']),
    Q('"Adolescence" là giai đoạn?', ['Trưởng thành', 'Thơ ấu', 'Vị thành niên (10-19)', 'Lão hóa'], 2, '"Adolescence" = tuổi vị thành niên.', ['Sai — "trưởng thành" là "adulthood", sau tuổi vị thành niên.', 'Sai — "thơ ấu" là "childhood", trước tuổi vị thành niên.', 'Đúng — "adolescence" = tuổi vị thành niên (khoảng 10-19 tuổi).', 'Sai — "lão hóa" là "ageing", giai đoạn cuối đời.']),
    Q('Chọn từ phù hợp: Many teens feel _____ about exams.', ['anxiousness', 'anxiously', 'anxiety', 'anxious'], 3, 'Sau "feel" + tính từ ⇒ "anxious".', ['Sai — "anxiousness" là danh từ; sau "feel" cần tính từ.', 'Sai — "anxiously" là trạng từ; "feel" là động từ nối nên cần tính từ.', 'Sai — "anxiety" là danh từ (sự lo lắng), không đi sau "feel" làm bổ ngữ tính từ.', 'Đúng — "feel + adj": feel anxious (cảm thấy lo lắng).']),
    Q('"Self-confidence" nghĩa là?', ['Sự tự kỷ', 'Tự ti (low self-esteem - khái niệm trái nghĩa)', 'Tự lập', 'Sự tự tin'], 3, '"Self-confidence" = sự tự tin.', ['Sai — "tự kỷ" là "autism", khái niệm hoàn toàn khác.', 'Sai — "tự ti" là "low self-esteem", trái nghĩa với self-confidence.', 'Sai — "tự lập" là "independence", không phải "self-confidence".', 'Đúng — "self-confidence" = sự tự tin vào bản thân.']),
  ]),

  M(6, 'Teen Stress — Reported speech (statements)', [
    Q('Câu tường thuật của: He said, "I am tired."', ['He said I was tired.', 'He said I am tired.', 'He said he is tired.', 'He said he was tired.'], 3, 'Lùi thì: am → was; "I" → "he".', ['Sai — đại từ "I" phải đổi thành "he" theo người nói (He).', 'Sai — phải lùi thì "am" → "was" và đổi "I" → "he".', 'Sai — đúng đại từ "he" nhưng thiếu lùi thì: "is" → "was".', 'Đúng — lùi thì am → was, đổi "I" → "he": He said he was tired.']),
    Q('Câu tường thuật của: She said, "I will come tomorrow."', ['She said she would come tomorrow.', 'She said she would come the next day.', 'She said she will come tomorrow.', 'She said she comes tomorrow.'], 1, 'Will → would; tomorrow → the next day/the following day.', ['Sai — đã lùi "will" → "would" nhưng "tomorrow" phải đổi thành "the next day".', 'Đúng — will → would và tomorrow → the next day (lùi cả thì lẫn trạng từ thời gian).', 'Sai — chưa lùi thì: "will" phải thành "would".', 'Sai — "comes" sai thì; tường thuật của "will come" là "would come".']),
    Q('"He said, \'I have finished my homework.\'" → ?', ['He said he has finished his homework.', 'He said he had finished his homework.', 'He said he finished his homework.', 'He said I have finished my homework.'], 1, 'Present perfect → past perfect (had finished).', ['Sai — chưa lùi thì: present perfect "has finished" phải thành "had finished".', 'Đúng — present perfect → past perfect: had finished; "my" → "his".', 'Sai — "finished" là quá khứ đơn; present perfect phải lùi thành past perfect.', 'Sai — đại từ "I/my" phải đổi thành "he/his" và phải lùi thì.']),
    Q('Khi tường thuật, "this" thường đổi thành?', ['that', 'those (chỉ đổi từ "these", không phải "this")', 'these (giữ nguyên - không thay đổi khi tường thuật)', 'it (chỉ thay khi nhắc lại danh từ đã biết)'], 0, 'Đại từ chỉ định: this → that; these → those.', ['Đúng — đại từ chỉ định "this" đổi thành "that" khi tường thuật.', 'Sai — "those" là dạng đổi của "these" (số nhiều), không phải "this".', 'Sai — "these" không giữ nguyên; số nhiều "these" → "those".', 'Sai — "it" chỉ dùng khi nhắc lại danh từ đã biết, không phải quy tắc chung cho "this".']),
    Q('"yesterday" trong câu tường thuật đổi thành?', ['the day before / the previous day', 'today (chỉ dùng khi "today" → "that day")', 'tomorrow', 'last day'], 0, 'Trạng từ thời gian: yesterday → the day before/the previous day.', ['Đúng — "yesterday" lùi thành "the day before" / "the previous day".', 'Sai — "today" là dạng đổi của "today" → "that day", không phải của "yesterday".', 'Sai — "tomorrow" chỉ tương lai, ngược hướng với "yesterday".', 'Sai — "last day" không phải cụm chuẩn; đúng là "the day before/the previous day".']),
    Q('Khi tường thuật, "here" đổi thành?', ['here (giữ nguyên - không đổi khi tường thuật)', 'somewhere', 'where (đại từ quan hệ chỉ nơi, không dùng tường thuật)', 'there'], 3, 'Đại từ chỉ nơi: here → there.', ['Sai — "here" không giữ nguyên; khi tường thuật đổi thành "there".', 'Sai — "somewhere" nghĩa "đâu đó", không phải dạng đổi của "here".', 'Sai — "where" là đại từ quan hệ chỉ nơi, không dùng để thay "here".', 'Đúng — trạng từ chỉ nơi "here" đổi thành "there" khi tường thuật.']),
  ]),

  M(7, 'Reported speech — Questions, Commands', [
    Q('"He asked me, \'Where do you live?\'" → ?', ['He asked me where I live.', 'He asked me where did I live.', 'He asked me where do I live.', 'He asked me where I lived.'], 3, 'Câu hỏi WH → S + V; lùi thì: do live → lived.', ['Sai — đã về trật tự S + V nhưng chưa lùi thì: "live" phải thành "lived".', 'Sai — tường thuật câu hỏi không giữ đảo ngữ "did I"; phải bỏ trợ động từ.', 'Sai — phải đưa về trật tự bình thường và lùi thì, không giữ "do".', 'Đúng — WH-question về trật tự "where I lived"; lùi thì do live → lived.']),
    Q('Câu tường thuật của: She asked, "Are you happy?"', ['She asked am I happy.', 'She asked if I was happy.', 'She asked I was happy.', 'She asked if I am happy.'], 1, 'Yes/No question → if/whether + S + V (lùi thì).', ['Sai — câu hỏi Yes/No phải thêm "if/whether" và bỏ đảo ngữ "am I".', 'Đúng — Yes/No question → if + S + V, lùi thì: are → was.', 'Sai — thiếu "if/whether" để nối câu hỏi Yes/No.', 'Sai — đã có "if" nhưng chưa lùi thì: "am" phải thành "was".']),
    Q('"He said to me, \'Open the door!\'" → ?', ['He told me opened the door.', 'He told me open the door.', 'He told me to open the door.', 'He said me to open the door.'], 2, 'Câu mệnh lệnh: told/asked + sb + (not) to + V.', ['Sai — mệnh lệnh dùng "to + V nguyên thể", không phải "opened".', 'Sai — thiếu "to": cấu trúc là "told sb to + V".', 'Đúng — mệnh lệnh: told + sb + to + V (He told me to open the door).', 'Sai — "say" không đi với tân ngữ kiểu "say me"; phải dùng "told me to".']),
    Q('"She said, \'Don\'t go out!\'" → ?', ['She said us don\'t go out.', 'She told us to don\'t go out.', 'She said don\'t go out.', 'She told us not to go out.'], 3, 'Mệnh lệnh phủ định: told + sb + not to + V.', ['Sai — "say us" sai; phải dùng "told us" và "not to go".', 'Sai — phủ định là "not to + V", không phải "to don\'t".', 'Sai — thiếu tân ngữ và sai cấu trúc; phải là "told us not to go out".', 'Đúng — mệnh lệnh phủ định: told + sb + not to + V.']),
    Q('"He asked, \'Who is calling?\'" → ?', ['He asked who called me.', 'He asked who called.', 'He asked who was calling.', 'He asked who is calling.'], 2, 'Câu hỏi WH (subject): who is → who was (lùi thì).', ['Sai — "called me" đổi nghĩa và sai thì; phải giữ "was calling".', 'Sai — "called" mất nghĩa tiếp diễn; gốc là "is calling" → "was calling".', 'Đúng — WH-subject question: who is calling → who was calling (lùi thì).', 'Sai — chưa lùi thì: "is calling" phải thành "was calling".']),
    Q('Trong câu tường thuật câu hỏi, trật tự từ phải?', ['Theo trật tự bình thường (S + V)', 'Cả B và C', 'Đảo ngữ', 'Bỏ trợ động từ'], 1, 'Khi tường thuật: đưa về trật tự bình thường + bỏ trợ động từ do/does/did.', ['Sai — đây chỉ là một phần; còn phải bỏ trợ động từ do/does/did nữa.', 'Đúng — vừa đưa về trật tự bình thường (S + V) vừa bỏ trợ động từ.', 'Sai — câu tường thuật KHÔNG dùng đảo ngữ, phải về trật tự bình thường.', 'Sai — bỏ trợ động từ là đúng nhưng còn cần đưa về trật tự S + V nữa.']),
  ]),

  M(8, 'Life in the Past — Vocabulary', [
    Q('"In the past" nghĩa là?', ['Ngày mai', 'Trong quá khứ', 'Hiện tại', 'Trong tương lai'], 1, '"In the past" = trong quá khứ.', ['Sai — "ngày mai" là "tomorrow", chỉ tương lai.', 'Đúng — "in the past" = trong quá khứ.', 'Sai — "hiện tại" là "at present/now", không phải "in the past".', 'Sai — "trong tương lai" là "in the future", ngược nghĩa.']),
    Q('"Used to + V" diễn tả?', ['Tương lai', 'Thói quen hiện tại', 'Hành động đang xảy ra', 'Thói quen trong quá khứ không còn nữa'], 3, '"Used to + V" = đã từng (quá khứ, không còn).', ['Sai — "used to" nói về quá khứ, không phải tương lai.', 'Sai — thói quen hiện tại dùng "usually + present simple", không dùng "used to".', 'Sai — hành động đang xảy ra dùng thì tiếp diễn, không phải "used to".', 'Đúng — "used to + V" = thói quen quá khứ nay không còn nữa.']),
    Q('Chọn dạng đúng: He _____ to live in Hanoi.', ['using (V-ing - không đúng cấu trúc "used to")', 'used', 'uses (hiện tại đơn - sai thì)', 'use (nguyên thể - thiếu "-d" của "used to")'], 1, 'Cấu trúc: used to + V nguyên.', ['Sai — "using" (V-ing) không tạo thành cấu trúc "used to".', 'Đúng — "used to + V": He used to live in Hanoi.', 'Sai — "uses" là hiện tại đơn, không diễn tả thói quen quá khứ.', 'Sai — "use" thiếu "-d"; phải là "used to".']),
    Q('Phủ định của "used to" là?', ['wasn\'t used to', 'don\'t use to', 'didn\'t used to', 'didn\'t use to'], 3, 'Phủ định: didn\'t use to + V.', ['Sai — "wasn\'t used to" mang nghĩa "không quen với" (be used to), khác nghĩa.', 'Sai — phải dùng trợ động từ quá khứ "didn\'t", không phải "don\'t".', 'Sai — sau "didn\'t" phải là "use" (nguyên thể), không phải "used".', 'Đúng — phủ định: didn\'t use to + V (bỏ "-d" sau "did").']),
    Q('"Traditional" có nghĩa?', ['Mới mẻ', 'Truyền thống', 'Lạ thường', 'Hiện đại'], 1, '"Traditional" = thuộc truyền thống.', ['Sai — "mới mẻ" là "new/novel", trái với truyền thống.', 'Đúng — "traditional" = thuộc về truyền thống.', 'Sai — "lạ thường" là "strange/unusual", không liên quan.', 'Sai — "hiện đại" là "modern", trái nghĩa với "traditional".']),
    Q('"Generation" nghĩa là?', ['Năm (year - đơn vị thời gian ngắn hơn)', 'Thập kỷ (decade - 10 năm, khác "thế hệ")', 'Thế hệ', 'Thế kỷ'], 2, '"Generation" = thế hệ (ông bà, cha mẹ, con cái…).', ['Sai — "năm" là "year", đơn vị thời gian, không phải "generation".', 'Sai — "thập kỷ" là "decade" (10 năm), khác với "thế hệ".', 'Đúng — "generation" = thế hệ (ông bà, cha mẹ, con cái).', 'Sai — "thế kỷ" là "century" (100 năm), không phải "generation".']),
  ]),

  M(9, 'Life in the Past — Wishes (Type 2)', [
    Q('Cấu trúc câu ước hiện tại?', ['S wish + S + will + V', 'S wish + S + V (past simple)', 'S wish + S + V (past perfect)', 'S wish + S + V (present simple)'], 1, 'Wish + S + V (quá khứ đơn) = ước về hiện tại không có thật.', ['Sai — "will" diễn tả mong muốn thay đổi (wish + would), không phải ước hiện tại.', 'Đúng — wish + past simple = ước về hiện tại trái thực tế.', 'Sai — wish + past perfect là ước về quá khứ, không phải hiện tại.', 'Sai — wish không đi với present simple; phải lùi về past simple.']),
    Q('Hoàn thành: I wish I _____ taller.', ['am (hiện tại đơn - không dùng sau "wish")', 'was (chấp nhận trong văn nói, kém chuẩn mực)', 'were', 'will be'], 2, 'Wish + S + were (cho mọi ngôi) trong văn trang trọng; cũng chấp nhận "was".', ['Sai — "am" (hiện tại đơn) không dùng sau "wish"; phải lùi thì.', 'Sai — "was" chỉ chấp nhận trong văn nói; chuẩn mực dùng "were".', 'Đúng — wish + were cho mọi ngôi (văn trang trọng): I wish I were taller.', 'Sai — "will be" diễn tả tương lai, không hợp với ước hiện tại trái thực tế.']),
    Q('"I wish I knew the answer" nghĩa?', ['Tôi ước tôi biết câu trả lời (hiện tại không biết)', 'Tôi sẽ biết', 'Tôi biết câu trả lời', 'Tôi đã biết'], 0, 'Wish + past = ước hiện tại trái với thực tế.', ['Đúng — wish + past simple = ước hiện tại trái thực tế (thực ra hiện không biết).', 'Sai — câu này nói về ước ở hiện tại, không phải tương lai "sẽ biết".', 'Sai — thực tế là KHÔNG biết; "knew" sau "wish" là giả định trái thực tế.', 'Sai — "đã biết" là quá khứ; đây là ước về hiện tại (wish + past = hiện tại).']),
    Q('Cấu trúc câu ước về tương lai (mong muốn thay đổi tình huống)?', ['S wish + S + can + V', 'S wish + S + V (past)', 'S wish + S + would + V', 'S wish + S + will + V'], 2, '"I wish she would call me" = mong cô ấy gọi.', ['Sai — không dùng "can" trực tiếp; muốn nói khả năng dùng "could".', 'Sai — wish + past là ước hiện tại, không phải mong muốn thay đổi tương lai.', 'Đúng — wish + would + V = mong muốn ai đó/điều gì thay đổi (I wish she would call me).', 'Sai — sau "wish" không dùng "will"; phải lùi thành "would".']),
    Q('Hoàn thành: I wish my brother _____ less video games.', ['plays (hiện tại đơn - sai thì sau "wish")', 'played', 'is playing', 'will play'], 1, 'Wish + past simple cho việc không có thật ở hiện tại.', ['Sai — "plays" hiện tại đơn không dùng sau "wish"; phải lùi thì.', 'Đúng — wish + past simple: I wish my brother played less.', 'Sai — "is playing" hiện tại tiếp diễn không dùng sau "wish".', 'Sai — "will play" tương lai; ước hiện tại trái thực tế cần past simple.']),
    Q('"If only I had more time" tương đương?', ['I wish I had more time', 'I would have more time', 'I wish I have more time', 'I had more time'], 0, '"If only" = "I wish" (mạnh hơn).', ['Đúng — "if only" = "I wish" (nhấn mạnh hơn): I wish I had more time.', 'Sai — đây là mệnh đề chính của câu điều kiện, không phải câu ước tương đương.', 'Sai — sau "wish" phải lùi thì: "had", không phải "have".', 'Sai — "I had more time" là câu trần thuật quá khứ, không phải câu ước.']),
  ]),

  M(10, 'Wonders of Viet Nam — Vocabulary', [
    Q('"Wonder" trong "Wonders of Vietnam" nghĩa là?', ['Kỳ quan', 'Câu hỏi', 'Sự ngạc nhiên', 'Ý tưởng'], 0, '"Wonder" = kỳ quan, danh lam thắng cảnh.', ['Đúng — trong ngữ cảnh này "wonder" = kỳ quan, danh thắng.', 'Sai — "câu hỏi" là "question"; "wonder" (động từ) có nghĩa "tự hỏi" nhưng ở đây là danh từ.', 'Sai — "sự ngạc nhiên" là một nghĩa khác của "wonder", không hợp ngữ cảnh kỳ quan.', 'Sai — "ý tưởng" là "idea", không phải nghĩa của "wonder".']),
    Q('"Heritage" nghĩa là?', ['Du khách', 'Di sản', 'Phong cảnh', 'Hướng dẫn viên'], 1, '"Heritage" = di sản (văn hóa, thiên nhiên).', ['Sai — "du khách" là "tourist", không phải "heritage".', 'Đúng — "heritage" = di sản (cultural/natural heritage).', 'Sai — "phong cảnh" là "landscape", không phải "heritage".', 'Sai — "hướng dẫn viên" là "guide", không liên quan.']),
    Q('"Landscape" có nghĩa?', ['Thành phố', 'Du khách (tourist - sai khái niệm)', 'Cảnh quan, phong cảnh', 'Công trình'], 2, '"Landscape" = phong cảnh.', ['Sai — "thành phố" là "city", không phải "landscape".', 'Sai — "du khách" là "tourist", sai khái niệm.', 'Đúng — "landscape" = cảnh quan, phong cảnh thiên nhiên.', 'Sai — "công trình" là "construction/structure", không phải "landscape".']),
    Q('"Ha Long Bay" được UNESCO công nhận là?', ['Di sản văn hóa', 'Di sản hỗn hợp', 'Di sản thiên nhiên thế giới', 'Di sản phi vật thể'], 2, 'Vịnh Hạ Long là di sản thiên nhiên thế giới (Natural Heritage).', ['Sai — di sản văn hóa (cultural heritage) là loại khác; Hạ Long thuộc thiên nhiên.', 'Sai — di sản hỗn hợp (mixed) như Tràng An; Hạ Long là di sản thiên nhiên.', 'Đúng — Hạ Long là di sản thiên nhiên thế giới (Natural World Heritage).', 'Sai — di sản phi vật thể (intangible) như Nhã nhạc, không phải Hạ Long.']),
    Q('"Imperial" nghĩa là?', ['Thuộc đế chế/hoàng gia', 'Nghệ thuật', 'Hiện đại', 'Đơn giản'], 0, '"Imperial city" = kinh thành hoàng gia (vd Imperial City of Hue).', ['Đúng — "imperial" = thuộc đế chế/hoàng gia (Imperial City of Hue).', 'Sai — "nghệ thuật" là "art/artistic", không phải "imperial".', 'Sai — "hiện đại" là "modern", không liên quan.', 'Sai — "đơn giản" là "simple", trái với sự nguy nga hoàng gia.']),
    Q('"Mausoleum" có nghĩa?', ['Đền thờ', 'Bảo tàng', 'Lăng mộ', 'Cung điện'], 2, '"Mausoleum" = lăng mộ (vd Ho Chi Minh Mausoleum).', ['Sai — "đền thờ" là "temple", không phải "mausoleum".', 'Sai — "bảo tàng" là "museum", âm gần nhưng khác nghĩa.', 'Đúng — "mausoleum" = lăng mộ (Ho Chi Minh Mausoleum).', 'Sai — "cung điện" là "palace", không phải "mausoleum".']),
  ]),

  M(11, 'Wonders — Passive Voice (Review)', [
    Q('Cấu trúc bị động của thì hiện tại đơn?', ['have/has been + V3', 'was/were + V3', 'am/is/are + V3', 'will be + V3'], 2, 'Present simple passive: am/is/are + V3.', ['Sai — "have/has been + V3" là bị động hiện tại hoàn thành, không phải hiện tại đơn.', 'Sai — "was/were + V3" là bị động quá khứ đơn.', 'Đúng — bị động hiện tại đơn: am/is/are + V3.', 'Sai — "will be + V3" là bị động tương lai đơn.']),
    Q('Đổi sang bị động: "They build a new bridge."', ['A new bridge was built.', 'A new bridge built.', 'A new bridge is built.', 'A new bridge is being built.'], 2, 'Hiện tại đơn bị động: is + V3.', ['Sai — "was built" là quá khứ đơn; gốc "build" là hiện tại đơn.', 'Sai — thiếu động từ "be"; bị động cần "is + V3".', 'Đúng — hiện tại đơn bị động: is built.', 'Sai — "is being built" là hiện tại tiếp diễn, nhưng gốc là hiện tại đơn.']),
    Q('Đổi sang bị động: "They built this temple in 1010."', ['This temple has been built in 1010.', 'This temple built in 1010.', 'This temple was built in 1010.', 'This temple is built in 1010.'], 2, 'Past simple passive: was/were + V3.', ['Sai — "has been built" là hiện tại hoàn thành; có mốc "1010" nên dùng quá khứ đơn.', 'Sai — thiếu "be"; bị động cần "was built".', 'Đúng — quá khứ đơn bị động: was built (với mốc thời gian 1010).', 'Sai — "is built" là hiện tại đơn; gốc "built" là quá khứ.']),
    Q('Cấu trúc bị động hiện tại hoàn thành?', ['was/were + V3', 'will be + V3', 'has/have been + V3', 'is/are being + V3'], 2, 'Present perfect passive: has/have been + V3.', ['Sai — "was/were + V3" là bị động quá khứ đơn.', 'Sai — "will be + V3" là bị động tương lai.', 'Đúng — bị động hiện tại hoàn thành: has/have been + V3.', 'Sai — "is/are being + V3" là bị động hiện tại tiếp diễn.']),
    Q('Đổi sang bị động: "People will visit this place."', ['This place will be visited.', 'This place will visited.', 'This place is visited.', 'This place was visited.'], 0, 'Future passive: will be + V3.', ['Đúng — bị động tương lai: will be + V3 (will be visited).', 'Sai — thiếu "be"; phải là "will be visited".', 'Sai — "is visited" là hiện tại đơn; gốc "will visit" là tương lai.', 'Sai — "was visited" là quá khứ; gốc là tương lai "will visit".']),
    Q('Khi nào dùng câu bị động?', ['Khi muốn nói chủ ngữ', 'Khi muốn nhấn mạnh đối tượng nhận hành động', 'Khi không có động từ', 'Khi cần ngắn gọn'], 1, 'Bị động nhấn mạnh đối tượng chịu tác động hơn là người thực hiện.', ['Sai — bị động nhấn mạnh đối tượng nhận hành động, không phải chủ ngữ thực hiện.', 'Đúng — bị động nhấn mạnh đối tượng chịu tác động hơn là người thực hiện.', 'Sai — câu bị động vẫn có động từ (be + V3).', 'Sai — bị động thường dài hơn chủ động, không phải để ngắn gọn.']),
  ]),

  M(12, 'Viet Nam Then and Now — Vocabulary', [
    Q('"Then" trong "Vietnam then and now" nghĩa là?', ['Khi đó (trước đây)', 'Sau đó', 'Tiếp theo', 'Lúc đó'], 0, '"Then" trong ngữ cảnh này = trước đây (in the past).', ['Đúng — "then" đối lập với "now" nên nghĩa là "khi đó/trước đây".', 'Sai — "sau đó" cũng là một nghĩa của "then" nhưng không hợp cặp "then and now".', 'Sai — "tiếp theo" là "next", không hợp ngữ cảnh "then and now".', 'Sai — "lúc đó" gần đúng nhưng cặp "then and now" nhấn nghĩa "trước đây" so với hiện tại.']),
    Q('"Develop" có nghĩa?', ['Phá hủy', 'Đánh giá', 'Phát triển', 'Bỏ qua'], 2, '"Develop" = phát triển.', ['Sai — "phá hủy" là "destroy", trái nghĩa với "develop".', 'Sai — "đánh giá" là "evaluate", không phải "develop".', 'Đúng — "develop" = phát triển, mở mang.', 'Sai — "bỏ qua" là "ignore/skip", không liên quan.']),
    Q('"Modernize" nghĩa là?', ['Cổ xưa hóa', 'Hiện đại hóa', 'Đơn giản hóa', 'Tự nhiên hóa'], 1, '"Modernize" = hiện đại hóa.', ['Sai — đuôi "-ize" nghĩa "làm cho"; "modern" là hiện đại nên không phải "cổ xưa hóa".', 'Đúng — "modernize" = hiện đại hóa (modern + ize).', 'Sai — "đơn giản hóa" là "simplify", không phải "modernize".', 'Sai — "tự nhiên hóa" là "naturalize", khác nghĩa.']),
    Q('Chọn từ phù hợp: Vietnam has _____ greatly since 1986.', ['changes', 'change', 'changed', 'changing'], 2, 'Sau "has" + V3 (present perfect): changed.', ['Sai — "changes" là hiện tại đơn; sau "has" phải là V3.', 'Sai — "change" nguyên thể; present perfect cần "has + V3".', 'Đúng — "has changed" (present perfect), đi với "since 1986".', 'Sai — "changing" là V-ing; sau "has" để tạo perfect phải là V3.']),
    Q('"Renovation" (đổi mới) ở Việt Nam bắt đầu năm?', ['1986', '1995', '2000', '1975'], 0, 'Đổi mới ("Đổi mới policy") chính thức bắt đầu từ Đại hội VI (1986).', ['Đúng — chính sách Đổi mới bắt đầu từ Đại hội VI năm 1986.', 'Sai — 1995 là năm Việt Nam gia nhập ASEAN, không phải mốc Đổi mới.', 'Sai — 2000 không phải mốc bắt đầu Đổi mới.', 'Sai — 1975 là năm thống nhất đất nước, trước Đổi mới hơn 10 năm.']),
    Q('"Modern" có nghĩa?', ['Nông thôn', 'Truyền thống', 'Cổ xưa', 'Hiện đại'], 3, '"Modern" = hiện đại; "ancient" = cổ xưa.', ['Sai — "nông thôn" là "rural", không phải "modern".', 'Sai — "truyền thống" là "traditional", không phải "modern".', 'Sai — "cổ xưa" là "ancient", trái nghĩa với "modern".', 'Đúng — "modern" = hiện đại; trái nghĩa là "ancient".']),
  ]),

  M(13, 'Recipes and Eating Habits — Vocabulary + Quantifiers', [
    Q('"Recipe" có nghĩa?', ['Thực đơn', 'Công thức nấu ăn', 'Hóa đơn', 'Bàn ăn'], 1, '"Recipe" = công thức nấu ăn.', ['Sai — "thực đơn" là "menu", không phải "recipe".', 'Đúng — "recipe" = công thức nấu ăn (hướng dẫn từng bước).', 'Sai — "hóa đơn" là "bill/receipt"; lưu ý "receipt" dễ nhầm với "recipe".', 'Sai — "bàn ăn" là "dining table", không liên quan.']),
    Q('"Ingredient" nghĩa là?', ['Dụng cụ', 'Nguyên liệu', 'Người nấu ăn', 'Công thức (recipe - dễ nhầm với ingredient)'], 1, '"Ingredient" = nguyên liệu/thành phần.', ['Sai — "dụng cụ" là "utensil/tool", không phải "ingredient".', 'Đúng — "ingredient" = nguyên liệu, thành phần của món ăn.', 'Sai — "người nấu ăn" là "cook/chef", không liên quan.', 'Sai — "công thức" là "recipe", dễ nhầm nhưng khác với "ingredient".']),
    Q('"A pinch of salt" nghĩa là?', ['Một thìa muối', 'Một bịch muối', 'Một nhúm muối', 'Một cốc muối'], 2, '"A pinch of" = một nhúm (rất ít).', ['Sai — "một thìa" là "a spoon of", nhiều hơn một nhúm.', 'Sai — "một bịch" là "a packet/bag of", lượng lớn.', 'Đúng — "a pinch of" = một nhúm (kẹp giữa ngón tay, rất ít).', 'Sai — "một cốc" là "a cup of", lượng lớn hơn nhiều.']),
    Q('Chọn từ chỉ lượng đúng: How _____ sugar do you need?', ['few (dùng cho danh từ đếm được số nhiều)', 'some (dùng trong câu khẳng định, không trong câu hỏi)', 'much', 'many (dùng cho danh từ đếm được số nhiều)'], 2, '"Sugar" là danh từ không đếm được ⇒ "much".', ['Sai — "few" dùng cho danh từ đếm được số nhiều, không cho "sugar".', 'Sai — "some" dùng trong câu khẳng định, không hỏi "how some".', 'Đúng — "sugar" không đếm được ⇒ how much.', 'Sai — "many" dùng cho danh từ đếm được; "sugar" không đếm được.']),
    Q('"A loaf of bread" có nghĩa?', ['Một lát bánh', 'Một chiếc bánh ngọt', 'Một ổ bánh mì', 'Một mẩu bánh'], 2, '"A loaf of bread" = một ổ bánh mì.', ['Sai — "một lát" là "a slice of bread", không phải "a loaf".', 'Sai — "bánh ngọt" là "cake", không phải "bread".', 'Đúng — "a loaf of bread" = một ổ bánh mì nguyên.', 'Sai — "một mẩu" là "a piece of bread", lượng nhỏ.']),
    Q('"Stir" có nghĩa?', ['Khuấy', 'Cắt (cut - thao tác dao kéo)', 'Đập (beat - nghĩa khác trong nấu ăn)', 'Đổ (pour - rót chất lỏng)'], 0, '"Stir" = khuấy đều.', ['Đúng — "stir" = khuấy đều (vd stir the soup).', 'Sai — "cắt" là "cut", thao tác dao kéo.', 'Sai — "đập (trứng)" là "beat", khác với "stir".', 'Sai — "đổ/rót" là "pour", không phải "stir".']),
  ]),

  M(14, 'Tourism — Vocabulary', [
    Q('"Tourist" và "tourism" khác nhau ở?', ['Đồng nghĩa', 'Tourist là chỗ ở', 'Tourism là du khách', 'Tourist là người, tourism là ngành/hoạt động'], 3, '"Tourist" = du khách; "tourism" = ngành du lịch.', ['Sai — hai từ không đồng nghĩa: một chỉ người, một chỉ ngành.', 'Sai — "tourist" là du khách (người), không phải chỗ ở.', 'Sai — ngược lại: "tourism" là ngành, "tourist" mới là du khách.', 'Đúng — "tourist" = du khách (người); "tourism" = ngành/hoạt động du lịch.']),
    Q('"Sightseeing" có nghĩa?', ['Mua sắm', 'Chụp ảnh', 'Ngắm cảnh, tham quan', 'Ăn uống'], 2, '"Go sightseeing" = đi tham quan ngắm cảnh.', ['Sai — "mua sắm" là "shopping", không phải "sightseeing".', 'Sai — "chụp ảnh" là "taking photos", không phải nghĩa của "sightseeing".', 'Đúng — "sightseeing" = ngắm cảnh, tham quan (go sightseeing).', 'Sai — "ăn uống" là "eating/dining", không liên quan.']),
    Q('"Accommodation" là?', ['Phương tiện đi lại', 'Nơi ở (khách sạn, nhà trọ…)', 'Đồ ăn, ẩm thực (cuisine - sai khái niệm)', 'Người hướng dẫn'], 1, '"Accommodation" = chỗ ở khi đi du lịch.', ['Sai — "phương tiện đi lại" là "transport", không phải "accommodation".', 'Đúng — "accommodation" = nơi ở (khách sạn, nhà trọ) khi du lịch.', 'Sai — "ẩm thực" là "cuisine/food", sai khái niệm.', 'Sai — "người hướng dẫn" là "guide", không phải chỗ ở.']),
    Q('"Booking" nghĩa là?', ['Đặt chỗ/đặt phòng', 'Sách (book - dạng danh từ gốc, sai nghĩa)', 'Mua bán', 'Đăng ký'], 0, '"Booking" = đặt phòng/đặt vé.', ['Đúng — "booking" = việc đặt chỗ/đặt phòng/đặt vé.', 'Sai — "sách" là nghĩa danh từ gốc "book", không phải "booking".', 'Sai — "mua bán" là "buying/selling", không phải "booking".', 'Sai — "đăng ký" là "registration", khác với "booking".']),
    Q('"Round-trip ticket" là?', ['Vé tàu', 'Vé một chiều', 'Vé khứ hồi', 'Vé bay'], 2, '"Round-trip" = khứ hồi (đi + về); "one-way" = một chiều.', ['Sai — "vé tàu" là "train ticket", không nói rõ chiều đi.', 'Sai — "vé một chiều" là "one-way ticket", trái với "round-trip".', 'Đúng — "round-trip ticket" = vé khứ hồi (cả đi lẫn về).', 'Sai — "vé bay" là "plane ticket", không chỉ tính chất khứ hồi.']),
    Q('Chọn giới từ đúng: We arrived _____ Hanoi at 6 a.m.', ['at (dùng cho địa điểm cụ thể như sân bay)', 'on (dùng cho ngày tháng, không đi với địa điểm)', 'in', 'to (đi với "go to", không đi với "arrive")'], 2, '"Arrive in + thành phố lớn/quốc gia"; "arrive at + địa điểm cụ thể".', ['Sai — "arrive at" dùng cho địa điểm nhỏ/cụ thể; Hanoi là thành phố lớn nên dùng "in".', 'Sai — "on" dùng cho ngày tháng, không đi với địa điểm.', 'Đúng — "arrive in + thành phố lớn/quốc gia": arrive in Hanoi.', 'Sai — "arrive" không đi với "to"; "to" dùng với "go to".']),
  ]),

  M(15, 'English in the World — Conditional Type 1', [
    Q('Cấu trúc câu điều kiện loại 1?', ['If + S + V (past), S + would + V', 'If + S + V (present), S + will + V', 'If + S + had + V3, S + would have + V3', 'If + S + V, S + V'], 1, 'Loại 1: điều kiện có thật ở hiện tại/tương lai.', ['Sai — "If + past, would + V" là cấu trúc loại 2 (giả định hiện tại).', 'Đúng — loại 1: If + present simple, S + will + V.', 'Sai — "If + had V3, would have V3" là loại 3 (quá khứ trái thực tế).', 'Sai — "If + V, S + V" là loại 0 (sự thật hiển nhiên), không có "will".']),
    Q('Hoàn thành: If it _____ tomorrow, we will stay home.', ['rains', 'rained', 'is raining', 'will rain'], 0, 'If + present simple, S + will + V.', ['Đúng — mệnh đề "if" loại 1 dùng hiện tại đơn: If it rains.', 'Sai — "rained" (quá khứ) là loại 2; ở đây vế chính có "will" nên là loại 1.', 'Sai — "is raining" hiện tại tiếp diễn không hợp cấu trúc loại 1 ở đây.', 'Sai — KHÔNG dùng "will" trong mệnh đề "if" của loại 1.']),
    Q('Câu điều kiện loại 1 diễn tả?', ['Tình huống không có thật ở quá khứ', 'Tình huống có thật/có thể xảy ra ở tương lai', 'Tình huống không có thật ở hiện tại', 'Sự thật hiển nhiên'], 1, 'Loại 1 = điều kiện thực tế.', ['Sai — quá khứ không có thật là loại 3, không phải loại 1.', 'Đúng — loại 1 diễn tả điều kiện có thật/có thể xảy ra ở tương lai.', 'Sai — hiện tại không có thật là loại 2, không phải loại 1.', 'Sai — sự thật hiển nhiên là loại 0, không phải loại 1.']),
    Q('Hoàn thành: If you study hard, you _____ pass the exam.', ['would (dùng cho câu điều kiện loại 2)', 'will', 'are (động từ to-be, không phù hợp ngữ pháp)', 'might have'], 1, 'Loại 1: will + V.', ['Sai — "would" dùng cho loại 2; mệnh đề "if" ở hiện tại đơn nên là loại 1.', 'Đúng — loại 1: vế chính dùng will + V (will pass).', 'Sai — "are pass" sai ngữ pháp; cần "will + V nguyên".', 'Sai — "might have" thuộc loại 3 (quá khứ); ở đây là loại 1.']),
    Q('Câu nào là điều kiện loại 1?', ['If I were you, I would say sorry.', 'If I have time, I will visit you.', 'If you heat ice, it melts.', 'If I had known, I would have helped.'], 1, 'Có cấu trúc: If + present, S + will + V.', ['Sai — "If I were ... would" là loại 2 (giả định hiện tại).', 'Đúng — "If + present, S + will + V" là loại 1.', 'Sai — "If + present, S + present" là loại 0 (sự thật hiển nhiên).', 'Sai — "If + had V3, would have V3" là loại 3 (quá khứ trái thực tế).']),
    Q('"Unless" tương đương với?', ['If (chỉ điều kiện khẳng định, không phải phủ định)', 'Because', 'When (chỉ thời gian, không phải điều kiện phủ định)', 'If not'], 3, '"Unless" = "if … not" = "nếu không".', ['Sai — "if" là điều kiện khẳng định; "unless" mang nghĩa phủ định.', 'Sai — "because" chỉ nguyên nhân, không phải điều kiện.', 'Sai — "when" chỉ thời gian, không phải điều kiện phủ định.', 'Đúng — "unless" = "if ... not" = "nếu không".']),
  ]),

  M(16, 'Conditional Type 2 — Hypothetical situations', [
    Q('Cấu trúc câu điều kiện loại 2?', ['If + S + had + V3, S + would have + V3', 'If + S + V (present), S + will + V', 'If + S + V (past), S + V (past)', 'If + S + V (past simple), S + would/could + V'], 3, 'Loại 2: tình huống không có thật ở hiện tại/tương lai.', ['Sai — "If + had V3, would have V3" là loại 3 (quá khứ trái thực tế).', 'Sai — "If + present, will + V" là loại 1 (điều kiện có thật).', 'Sai — vế chính loại 2 dùng "would/could + V", không phải quá khứ đơn.', 'Đúng — loại 2: If + past simple, S + would/could + V.']),
    Q('Hoàn thành: If I _____ rich, I would buy a big house.', ['were', 'will be', 'was (chấp nhận văn nói, kém trang trọng)', 'am (hiện tại đơn - sai thì với loại 2)'], 0, 'Loại 2 dùng "were" cho mọi ngôi (văn trang trọng); "was" cũng được chấp nhận.', ['Đúng — loại 2 dùng "were" cho mọi ngôi: If I were rich.', 'Sai — "will be" thuộc loại 1; mệnh đề "if" loại 2 không dùng "will".', 'Sai — "was" chỉ chấp nhận trong văn nói; chuẩn mực dùng "were".', 'Sai — "am" (hiện tại đơn) sai thì với loại 2; phải dùng "were".']),
    Q('Câu "If I were you, I would study harder" diễn tả?', ['Khả năng cao', 'Hành động trong quá khứ', 'Lời khuyên/giả định trái thực tế', 'Sự thật'], 2, 'Loại 2 thường dùng cho lời khuyên ("If I were you…").', ['Sai — loại 2 là giả định trái thực tế, không phải khả năng cao (đó là loại 1).', 'Sai — đây nói về hiện tại trái thực tế, không phải hành động quá khứ.', 'Đúng — loại 2 dùng cho lời khuyên/giả định trái thực tế (If I were you).', 'Sai — "I were you" là giả định không có thật, không phải sự thật.']),
    Q('Hoàn thành: If she _____ his phone number, she would call him.', ['know (nguyên thể - thiếu chia thì quá khứ)', 'knows (hiện tại đơn - sai thì với loại 2)', 'knew', 'has known'], 2, 'Loại 2: If + past simple.', ['Sai — "know" thiếu chia thì; loại 2 cần quá khứ đơn "knew".', 'Sai — "knows" hiện tại đơn thuộc loại 1; loại 2 cần "knew".', 'Đúng — loại 2: If + past simple (knew), vế chính "would call".', 'Sai — "has known" là hiện tại hoàn thành, không dùng trong mệnh đề "if" loại 2.']),
    Q('Trong câu điều kiện loại 2, mệnh đề chính dùng?', ['Will + V', 'Would/could/might + V', 'Have + V3', 'Past simple'], 1, 'Mệnh đề chính dùng would/could/might + V nguyên.', ['Sai — "will + V" là vế chính của loại 1, không phải loại 2.', 'Đúng — vế chính loại 2: would/could/might + V nguyên.', 'Sai — "have + V3" là present perfect, không phải vế chính loại 2.', 'Sai — past simple là mệnh đề "if" của loại 2, không phải vế chính.']),
    Q('Câu nào sai?', ['If he knows, he will tell.', 'If she was rich, she would travel.', 'If I had time, I would go.', 'If I were you, I would help.'], 1, 'Câu D nên là "she were rich" (tuy nhiên "was" cũng dần được chấp nhận; trong ngữ pháp truyền thống là sai).', ['Sai (câu này đúng) — "If he knows, he will tell" là loại 1 hợp lệ.', 'Đúng (đây là câu sai) — ngữ pháp truyền thống yêu cầu "If she were rich" cho loại 2.', 'Sai (câu này đúng) — "If I had time, I would go" là loại 2 chuẩn.', 'Sai (câu này đúng) — "If I were you, I would help" là loại 2 chuẩn.']),
  ]),

  M(17, 'Conditional Type 3 — Past unreal situations', [
    Q('Cấu trúc câu điều kiện loại 3?', ['If + S + V (past), S + would + V', 'If + S + V (present), S + will + V', 'If + S + had + V3, S + would have + V3', 'If + S + had + V, S + will + V'], 2, 'Loại 3: tình huống không có thật trong quá khứ.', ['Sai — "If + past, would + V" là loại 2 (hiện tại trái thực tế).', 'Sai — "If + present, will + V" là loại 1 (điều kiện có thật).', 'Đúng — loại 3: If + had + V3, S + would have + V3.', 'Sai — vế chính loại 3 dùng "would have + V3", không phải "will + V".']),
    Q('Hoàn thành: If I _____ harder, I would have passed the exam.', ['had studied', 'studies', 'studied', 'study (nguyên thể - sai thì với loại 3)'], 0, 'Loại 3: If + S + had + V3.', ['Đúng — loại 3 mệnh đề "if": had + V3 (had studied).', 'Sai — "studies" hiện tại đơn thuộc loại 1, không phải loại 3.', 'Sai — "studied" quá khứ đơn thuộc loại 2; loại 3 cần "had studied".', 'Sai — "study" nguyên thể sai thì; loại 3 cần "had + V3".']),
    Q('Câu "If she had known, she would have come" có nghĩa?', ['Cô ấy sẽ biết', 'Cô ấy đã biết và đã đến', 'Cô ấy không biết nên không đến (trái thực tế quá khứ)', 'Cô ấy biết và sẽ đến'], 2, 'Loại 3 ám chỉ điều đã không xảy ra trong quá khứ.', ['Sai — loại 3 nói về quá khứ, không phải "sẽ biết" (tương lai).', 'Sai — thực tế là cô ấy KHÔNG biết và KHÔNG đến (trái thực tế).', 'Đúng — loại 3: thực tế cô ấy không biết nên đã không đến (quá khứ trái thực tế).', 'Sai — loại 3 ám chỉ điều đã không xảy ra, không phải "biết và sẽ đến".']),
    Q('Hoàn thành: If he hadn\'t been late, he _____ the train.', ['caught', 'catches', 'would have caught', 'would catch'], 2, 'Mệnh đề chính loại 3: would have + V3.', ['Sai — "caught" quá khứ đơn không phải vế chính loại 3.', 'Sai — "catches" hiện tại đơn sai thì hoàn toàn với loại 3.', 'Đúng — vế chính loại 3: would have + V3 (would have caught).', 'Sai — "would catch" là vế chính loại 2; loại 3 cần "would have caught".']),
    Q('Sự khác biệt giữa loại 2 và loại 3?', ['Loại 2 chắc chắn hơn', 'Loại 2 nói về hiện tại không có thật, loại 3 về quá khứ không có thật', 'Không khác nhau', 'Loại 2 nói quá khứ, loại 3 nói tương lai'], 1, 'Loại 2: hiện tại/tương lai trái thực tế; loại 3: quá khứ trái thực tế.', ['Sai — cả hai đều là giả định trái thực tế; khác nhau ở mốc thời gian.', 'Đúng — loại 2 về hiện tại trái thực tế, loại 3 về quá khứ trái thực tế.', 'Sai — hai loại khác nhau rõ rệt về thời gian và cấu trúc thì.', 'Sai — ngược lại: loại 2 về hiện tại, loại 3 về quá khứ.']),
    Q('Hoàn thành: If you _____ me earlier, I could have helped you.', ['called', 'call (nguyên thể - sai thì với loại 3)', 'had called', 'have called'], 2, 'Loại 3: had + V3.', ['Sai — "called" quá khứ đơn thuộc loại 2; vế chính "could have helped" báo hiệu loại 3.', 'Sai — "call" nguyên thể sai thì với loại 3.', 'Đúng — loại 3 mệnh đề "if": had + V3 (had called).', 'Sai — "have called" hiện tại hoàn thành; loại 3 cần "had called".']),
  ]),

  M(18, 'Ôn tập học kỳ I', [
    Q('Bị động của "They are building a new school."?', ['A new school has been built.', 'A new school is being built.', 'A new school was built.', 'A new school is built.'], 1, 'Present continuous passive: is/are being + V3.', ['Sai — "has been built" là hiện tại hoàn thành; gốc "are building" là hiện tại tiếp diễn.', 'Đúng — hiện tại tiếp diễn bị động: is being built.', 'Sai — "was built" là quá khứ đơn; gốc là hiện tại tiếp diễn.', 'Sai — "is built" là hiện tại đơn; thiếu "being" của tiếp diễn.']),
    Q('Tường thuật: He said, "I went to the cinema last night."', ['He said he went to the cinema the previous night.', 'He said he has gone to the cinema last night.', 'A và B đều đúng', 'He said he had gone to the cinema the night before.'], 2, 'Cả "he went … the previous night" lẫn "he had gone … the night before" đều chuẩn.', ['Sai — câu này đúng nhưng chưa đủ; đáp án D cũng đúng nên phải chọn "cả hai".', 'Sai — "has gone ... last night" sai: "last night" không đi với hiện tại hoàn thành.', 'Đúng — cả A (giữ past simple) lẫn D (lùi thành past perfect) đều được chấp nhận.', 'Sai — câu này đúng nhưng đáp án A cũng đúng nên phải chọn "cả hai đều đúng".']),
    Q('Câu điều kiện loại 1: If it rains, we _____ stay home.', ['will', 'are (động từ to-be - sai cấu trúc loại 1)', 'have (thiếu V3, sai cấu trúc hoàn thành)', 'would (dùng cho điều kiện loại 2)'], 0, 'Loại 1: will + V.', ['Đúng — loại 1 vế chính: will + V (will stay).', 'Sai — "are stay" sai ngữ pháp; cần "will + V nguyên".', 'Sai — "have stay" sai; present perfect cần "have + V3" và không hợp loại 1.', 'Sai — "would" dùng cho loại 2; mệnh đề "if" ở hiện tại đơn nên là loại 1.']),
    Q('Câu ước: I wish I _____ younger.', ['will be', 'was (chấp nhận văn nói, kém chuẩn mực)', 'am (hiện tại đơn - sai thì sau "wish")', 'were'], 3, 'Wish + were cho mọi ngôi (trang trọng).', ['Sai — "will be" tương lai, không hợp ước hiện tại trái thực tế.', 'Sai — "was" chỉ chấp nhận trong văn nói; chuẩn mực dùng "were".', 'Sai — "am" hiện tại đơn không dùng sau "wish"; phải lùi thì.', 'Đúng — wish + were cho mọi ngôi (văn trang trọng): I wish I were younger.']),
    Q('"Although" có thể thay bằng?', ['Because', 'Even though, though', 'And (liên từ nối đẳng lập, không tương phản)', 'So (chỉ kết quả, không phải nhượng bộ)'], 1, '"Although", "though", "even though" đồng nghĩa.', ['Sai — "because" chỉ nguyên nhân, không phải nhượng bộ như "although".', 'Đúng — "although", "though", "even though" đồng nghĩa (mặc dù).', 'Sai — "and" nối đẳng lập, không diễn tả tương phản.', 'Sai — "so" chỉ kết quả, không phải nhượng bộ.']),
    Q('"Used to + V" diễn tả?', ['Hiện tại đơn', 'Hành động hoàn thành', 'Tương lai gần', 'Thói quen quá khứ'], 3, '"Used to" = đã từng (trong quá khứ).', ['Sai — hiện tại đơn diễn tả thói quen hiện tại, không phải "used to".', 'Sai — hành động hoàn thành dùng present/past perfect, không phải "used to".', 'Sai — tương lai gần dùng "be going to", không phải "used to".', 'Đúng — "used to + V" = thói quen quá khứ (đã từng, nay không còn).']),
  ]),

  // ──────────────── HK2 ────────────────
  M(19, 'Space Travel — Vocabulary', [
    Q('"Astronaut" có nghĩa?', ['Phi công', 'Lái xe', 'Phi hành gia', 'Kỹ sư hàng không (aerospace engineer - nghề liên quan)'], 2, '"Astronaut" = nhà du hành vũ trụ.', ['Sai — "phi công" là "pilot", lái máy bay chứ không bay vào vũ trụ.', 'Sai — "lái xe" là "driver", không liên quan vũ trụ.', 'Đúng — "astronaut" = phi hành gia, nhà du hành vũ trụ.', 'Sai — "kỹ sư hàng không" là "aerospace engineer", nghề liên quan nhưng khác "astronaut".']),
    Q('"Spaceship" là?', ['Tàu thủy', 'Tàu vũ trụ', 'Vệ tinh', 'Máy bay'], 1, '"Spaceship" = tàu vũ trụ.', ['Sai — "tàu thủy" là "ship/boat", đi trên biển.', 'Đúng — "spaceship" = tàu vũ trụ (space + ship).', 'Sai — "vệ tinh" là "satellite", không chở người như spaceship.', 'Sai — "máy bay" là "airplane", bay trong khí quyển.']),
    Q('"Galaxy" nghĩa là?', ['Mặt trăng', 'Ngôi sao', 'Thiên hà', 'Hành tinh'], 2, '"Galaxy" = thiên hà (chứa hàng tỷ ngôi sao).', ['Sai — "mặt trăng" là "moon", vệ tinh của Trái Đất.', 'Sai — "ngôi sao" là "star"; thiên hà chứa hàng tỷ ngôi sao.', 'Đúng — "galaxy" = thiên hà (vd Milky Way).', 'Sai — "hành tinh" là "planet", nhỏ hơn thiên hà rất nhiều.']),
    Q('"Solar system" là?', ['Hệ thống điện', 'Hệ năng lượng mặt trời', 'Hệ thống vũ trụ', 'Hệ Mặt Trời'], 3, '"Solar system" = Hệ Mặt Trời (Mặt Trời + các hành tinh).', ['Sai — "hệ thống điện" là "electrical system", không liên quan.', 'Sai — "hệ năng lượng mặt trời" là "solar power system", khác nghĩa thiên văn.', 'Sai — "hệ thống vũ trụ" quá rộng; "solar system" chỉ Hệ Mặt Trời.', 'Đúng — "solar system" = Hệ Mặt Trời (Mặt Trời và các hành tinh quay quanh).']),
    Q('"Orbit" có nghĩa?', ['Tốc độ', 'Trọng lực', 'Khoảng cách', 'Quỹ đạo'], 3, '"Orbit" = quỹ đạo (đường đi của hành tinh quanh sao).', ['Sai — "tốc độ" là "speed", không phải "orbit".', 'Sai — "trọng lực" là "gravity", không phải "orbit".', 'Sai — "khoảng cách" là "distance", không phải "orbit".', 'Đúng — "orbit" = quỹ đạo (đường hành tinh quay quanh sao).']),
    Q('"Launch" trong "launch a rocket" nghĩa là?', ['Lái (drive/pilot - thao tác khi đã bay)', 'Phóng', 'Hạ cánh', 'Sửa chữa'], 1, '"Launch" = phóng (tên lửa, vệ tinh).', ['Sai — "lái" là "drive/pilot", thao tác khi đang bay, không phải "launch".', 'Đúng — "launch" = phóng (tên lửa, vệ tinh).', 'Sai — "hạ cánh" là "land", trái với phóng lên.', 'Sai — "sửa chữa" là "repair", không liên quan.']),
  ]),

  M(20, 'Space Travel — Present Perfect', [
    Q('Thì hiện tại hoàn thành cấu tạo bởi?', ['have/has + V3', 'was/were + V-ing', 'am/is/are + V-ing', 'will + V'], 0, 'Present perfect: have/has + past participle (V3).', ['Đúng — present perfect = have/has + V3 (past participle).', 'Sai — "was/were + V-ing" là quá khứ tiếp diễn.', 'Sai — "am/is/are + V-ing" là hiện tại tiếp diễn.', 'Sai — "will + V" là tương lai đơn.']),
    Q('Câu "I have visited Hanoi" có nghĩa?', ['Tôi đã từng đến Hà Nội (kinh nghiệm)', 'Tôi đang ở Hà Nội', 'Tôi sẽ đến Hà Nội', 'Tôi không đến Hà Nội'], 0, 'Present perfect diễn tả kinh nghiệm tới hiện tại.', ['Đúng — present perfect diễn tả kinh nghiệm: đã từng đến Hà Nội.', 'Sai — "đang ở" dùng hiện tại tiếp diễn, không phải present perfect.', 'Sai — "sẽ đến" dùng tương lai, không phải present perfect.', 'Sai — câu này khẳng định, không phải phủ định "không đến".']),
    Q('Chọn dạng đúng: She _____ already finished her homework.', ['is (hiện tại đơn - sai thì hoàn thành)', 'have (chỉ dùng với I/you/we/they)', 'will (tương lai - sai thì hoàn thành)', 'has'], 3, 'She → has; "already" thường đi với present perfect.', ['Sai — "is finished" không tạo present perfect; cần "has + V3".', 'Sai — "have" dùng với I/you/we/they; "she" phải dùng "has".', 'Sai — "will" là tương lai; "already" báo hiệu present perfect.', 'Đúng — "she has already finished" (present perfect, ngôi thứ ba dùng has).']),
    Q('Trạng từ nào KHÔNG đi với present perfect?', ['never (đi với hoàn thành chỉ kinh nghiệm)', 'ever (đi với hoàn thành trong câu hỏi)', 'yesterday', 'just (đi với hoàn thành chỉ vừa xong)'], 2, '"Yesterday" đi với past simple, không đi với present perfect.', ['Sai — "never" đi với present perfect chỉ kinh nghiệm (have never been).', 'Sai — "ever" đi với present perfect trong câu hỏi (Have you ever...).', 'Đúng — "yesterday" là mốc quá khứ rõ ràng, đi với past simple.', 'Sai — "just" đi với present perfect chỉ việc vừa xong (have just).']),
    Q('Hoàn thành: NASA _____ many satellites into space.', ['launched', 'launches', 'is launching', 'has launched'], 3, 'Diễn tả hành động đã làm tới hiện tại ⇒ present perfect.', ['Sai — "launched" past simple chỉ sự việc đã xong, không nhấn liên hệ hiện tại.', 'Sai — "launches" hiện tại đơn diễn tả thói quen, không hợp ngữ cảnh thành tựu.', 'Sai — "is launching" hiện tại tiếp diễn chỉ một lần phóng đang diễn ra.', 'Đúng — "has launched" present perfect: thành tựu tích lũy tới hiện tại.']),
    Q('Sự khác biệt: "I have lost my key" vs "I lost my key yesterday"?', ['Câu 2 sai', 'Không khác nhau', 'Câu 1: tình trạng vẫn ảnh hưởng hiện tại; Câu 2: chỉ sự việc trong quá khứ', 'Câu 1 sai'], 2, 'Present perfect có liên quan đến hiện tại; past simple chỉ sự việc đã xong.', ['Sai — câu 2 đúng ngữ pháp (past simple với "yesterday").', 'Sai — hai câu khác nhau về liên hệ với hiện tại.', 'Đúng — câu 1 (present perfect) nhấn hậu quả hiện tại; câu 2 (past simple) chỉ kể sự việc quá khứ.', 'Sai — câu 1 đúng ngữ pháp (present perfect, không có mốc thời gian).']),
  ]),

  M(21, 'Changing Roles in Society — Vocabulary', [
    Q('"Gender equality" nghĩa là?', ['Bất bình đẳng giới', 'Bình đẳng giới', 'Phụ nữ', 'Phân biệt đối xử'], 1, '"Gender equality" = bình đẳng giới.', ['Sai — "bất bình đẳng giới" là "gender inequality", trái nghĩa.', 'Đúng — "gender equality" = bình đẳng giới.', 'Sai — "phụ nữ" là "women", chỉ một giới chứ không phải sự bình đẳng.', 'Sai — "phân biệt đối xử" là "discrimination", trái với bình đẳng.']),
    Q('"Role" có nghĩa?', ['Vai trò', 'Quy tắc', 'Vai diễn', 'Lối đi (road - âm gần "role" nhưng khác nghĩa)'], 0, '"Role" = vai trò trong xã hội/gia đình.', ['Đúng — "role" = vai trò (trong gia đình, xã hội).', 'Sai — "quy tắc" là "rule", âm gần nhưng khác nghĩa.', 'Sai — "vai diễn" cũng dùng "role" nhưng ở đây ngữ cảnh là vai trò xã hội.', 'Sai — "lối đi" là "road", phát âm gần "role" nhưng khác nghĩa.']),
    Q('"Working mother" là?', ['Mẹ thất nghiệp', 'Mẹ ở nhà', 'Người mẹ đi làm', 'Mẹ già'], 2, '"Working mother" = người mẹ vừa đi làm vừa chăm sóc con.', ['Sai — "thất nghiệp" là "unemployed", trái với "working".', 'Sai — "mẹ ở nhà" là "stay-at-home mother", không đi làm.', 'Đúng — "working mother" = người mẹ đi làm (vừa làm vừa chăm con).', 'Sai — "mẹ già" là "elderly mother", không nói về việc đi làm.']),
    Q('"Breadwinner" có nghĩa?', ['Người bán hàng', 'Người chiến thắng', 'Người trụ cột về tài chính trong gia đình', 'Người làm bánh'], 2, '"Breadwinner" = trụ cột kinh tế (kiếm tiền nuôi gia đình).', ['Sai — "người bán hàng" là "seller", không phải "breadwinner".', 'Sai — "người chiến thắng" là "winner" nhưng "breadwinner" là từ ghép nghĩa khác.', 'Đúng — "breadwinner" = trụ cột tài chính, kiếm tiền nuôi gia đình.', 'Sai — "người làm bánh" là "baker"; "breadwinner" không liên quan tới làm bánh.']),
    Q('"Stereotype" nghĩa là?', ['Quan điểm', 'Sự đa dạng', 'Khuôn mẫu, định kiến', 'Sự thật'], 2, '"Stereotype" = định kiến/khuôn mẫu xã hội.', ['Sai — "quan điểm" là "opinion/viewpoint", không phải định kiến cố hữu.', 'Sai — "sự đa dạng" là "diversity", trái với khuôn mẫu rập khuôn.', 'Đúng — "stereotype" = khuôn mẫu, định kiến (vd gender stereotype).', 'Sai — "sự thật" là "fact"; stereotype thường là định kiến chứ chưa chắc đúng.']),
    Q('Chọn từ phù hợp: Women have become more _____ in society.', ['independently', 'independent', 'depend', 'independence'], 1, 'Sau "more" + tính từ ⇒ "independent".', ['Sai — "independently" là trạng từ; sau "become more" cần tính từ.', 'Đúng — "more independent" (tính từ) sau động từ nối "become".', 'Sai — "depend" là động từ, không hợp sau "more".', 'Sai — "independence" là danh từ; cần tính từ sau "more".']),
  ]),

  M(22, 'Changing Roles — Passive Voice (Continued)', [
    Q('Cấu trúc bị động của thì tương lai gần (be going to)?', ['will be + V3', 'going to be + V3', 'be going to be + V3', 'is going to + V3'], 2, 'Future near passive: be going to be + V3.', ['Sai — "will be + V3" là bị động tương lai đơn, không phải "be going to".', 'Sai — thiếu động từ "be" trước "going to".', 'Đúng — bị động tương lai gần: be going to be + V3.', 'Sai — "is going to + V3" thiếu "be"; phải là "be going to be + V3".']),
    Q('Đổi sang bị động: "They are going to open a new park."', ['A new park is opened.', 'A new park is going to be opened.', 'A new park is being opened.', 'A new park will be opened.'], 1, 'Be going to be + V3.', ['Sai — "is opened" là hiện tại đơn; gốc là "be going to".', 'Đúng — bị động "be going to": is going to be opened.', 'Sai — "is being opened" là hiện tại tiếp diễn, không phải "be going to".', 'Sai — "will be opened" là tương lai đơn; gốc dùng "be going to".']),
    Q('Bị động của câu có 2 tân ngữ: "He gave me a present"?', ['A present was give me.', 'Me was given a present.', 'I was given a present (by him). / A present was given to me (by him).', 'I was give a present.'], 2, 'Có 2 cách: lấy tân ngữ gián tiếp hoặc trực tiếp làm chủ ngữ bị động.', ['Sai — "was give" sai; phải là V3 "given".', 'Sai — chủ ngữ phải là "I" (chủ cách), không phải "me" (tân cách).', 'Đúng — hai cách: "I was given a present" hoặc "A present was given to me".', 'Sai — "was give" sai dạng; phải dùng past participle "given".']),
    Q('Bị động của "Someone stole my bike."?', ['My bike has stolen.', 'My bike steals.', 'My bike was stolen.', 'My bike is stolen.'], 2, '"Someone" không đề cập tới ai cụ thể ⇒ bị động không cần "by".', ['Sai — "has stolen" là chủ động hoàn thành; bị động cần "has been stolen".', 'Sai — "steals" hiện tại đơn chủ động; gốc "stole" là quá khứ.', 'Đúng — quá khứ đơn bị động: was stolen (bỏ "by someone").', 'Sai — "is stolen" hiện tại đơn; gốc "stole" là quá khứ nên dùng "was stolen".']),
    Q('Khi nào bỏ "by + tác nhân" trong câu bị động?', ['Luôn luôn', 'Không bao giờ', 'Khi không biết hoặc không cần thiết', 'Khi nói về sự việc cụ thể'], 2, 'Bỏ "by sb" khi tác nhân không quan trọng/không biết.', ['Sai — không phải lúc nào cũng bỏ; có khi cần nêu tác nhân quan trọng.', 'Sai — vẫn có thể bỏ "by sb" khi tác nhân không rõ.', 'Đúng — bỏ "by + tác nhân" khi không biết hoặc không cần thiết.', 'Sai — sự việc cụ thể không phải tiêu chí; vấn đề là tác nhân có quan trọng không.']),
    Q('Bị động của "They have built a new bridge"?', ['A new bridge had been built.', 'A new bridge is built.', 'A new bridge has been built.', 'A new bridge was built.'], 2, 'Present perfect passive: has/have been + V3.', ['Sai — "had been built" là quá khứ hoàn thành; gốc "have built" là hiện tại hoàn thành.', 'Sai — "is built" là hiện tại đơn, không phải hoàn thành.', 'Đúng — present perfect bị động: has been built.', 'Sai — "was built" là quá khứ đơn; gốc là hiện tại hoàn thành.']),
  ]),

  M(23, 'My Future Career — Vocabulary', [
    Q('"Career" có nghĩa?', ['Công ty', 'Sự nghiệp', 'Công việc tạm thời', 'Tiền lương'], 1, '"Career" = sự nghiệp (dài hạn).', ['Sai — "công ty" là "company", không phải "career".', 'Đúng — "career" = sự nghiệp, con đường nghề nghiệp dài hạn.', 'Sai — "công việc tạm thời" là "temporary job", ngắn hạn hơn "career".', 'Sai — "tiền lương" là "salary", không phải "career".']),
    Q('"Job" và "career" khác nhau ở?', ['Đồng nghĩa', 'Job: công việc cụ thể; career: sự nghiệp dài hạn', 'Career ngắn hơn', 'Job dài hơn'], 1, '"Job" là công việc cụ thể; "career" là con đường nghề nghiệp.', ['Sai — hai từ không đồng nghĩa: một là công việc cụ thể, một là sự nghiệp.', 'Đúng — "job" là công việc cụ thể; "career" là con đường nghề nghiệp dài hạn.', 'Sai — ngược lại: "career" mang nghĩa dài hạn hơn "job".', 'Sai — ngược lại: "career" thường dài hạn hơn "job".']),
    Q('"Vocational training" là?', ['Học đại học', 'Đào tạo nghề', 'Du học', 'Học cao học'], 1, '"Vocational training" = đào tạo nghề.', ['Sai — "học đại học" là "university education", không phải đào tạo nghề.', 'Đúng — "vocational training" = đào tạo nghề (kỹ năng thực hành).', 'Sai — "du học" là "study abroad", không phải "vocational".', 'Sai — "học cao học" là "postgraduate study", khác đào tạo nghề.']),
    Q('"Apply for a job" nghĩa là?', ['Phỏng vấn', 'Làm việc', 'Bỏ việc', 'Nộp đơn xin việc'], 3, '"Apply for" = nộp đơn xin (việc/học bổng).', ['Sai — "phỏng vấn" là "interview", bước sau khi nộp đơn.', 'Sai — "làm việc" là "work", không phải "apply for".', 'Sai — "bỏ việc" là "quit/resign", trái với xin việc.', 'Đúng — "apply for a job" = nộp đơn xin việc.']),
    Q('"Resume" / "CV" là?', ['Sơ yếu lý lịch', 'Bằng cấp', 'Hợp đồng', 'Đơn xin việc'], 0, '"Resume" (AmE) / "CV" (Curriculum Vitae) = bản tóm tắt lý lịch nghề nghiệp.', ['Đúng — "resume/CV" = sơ yếu lý lịch (tóm tắt học vấn, kinh nghiệm).', 'Sai — "bằng cấp" là "qualification/degree", một phần của CV chứ không phải toàn bộ.', 'Sai — "hợp đồng" là "contract", không phải CV.', 'Sai — "đơn xin việc" là "application letter", khác với resume/CV.']),
    Q('"Salary" có nghĩa?', ['Phụ cấp', 'Tiền thưởng', 'Lương tháng', 'Tiền hưu'], 2, '"Salary" = lương (thường trả hàng tháng).', ['Sai — "phụ cấp" là "allowance", khoản phụ thêm ngoài lương.', 'Sai — "tiền thưởng" là "bonus", không phải lương cố định.', 'Đúng — "salary" = lương (thường trả hàng tháng).', 'Sai — "tiền hưu" là "pension", trả sau khi nghỉ hưu.']),
  ]),

  M(24, 'Relative Clauses — Defining (Mệnh đề quan hệ xác định)', [
    Q('Đại từ quan hệ nào thay cho người?', ['where (thay cho nơi chốn, không phải người)', 'which (thay cho vật, không phải người)', 'whose (chỉ sở hữu, không phải chủ ngữ người)', 'who, whom'], 3, '"Who" làm chủ ngữ, "whom" làm tân ngữ cho người.', ['Sai — "where" thay cho nơi chốn, không phải người.', 'Sai — "which" thay cho vật, không phải người.', 'Sai — "whose" chỉ quan hệ sở hữu, không làm chủ ngữ/tân ngữ chỉ người.', 'Đúng — "who" (chủ ngữ) và "whom" (tân ngữ) thay cho người.']),
    Q('Đại từ quan hệ nào thay cho vật?', ['which', 'whom (làm tân ngữ cho người, không cho vật)', 'who (chủ ngữ cho người, không cho vật)', 'when (thay cho thời gian, không cho vật)'], 0, '"Which" thay cho vật/động vật.', ['Đúng — "which" thay cho vật/động vật.', 'Sai — "whom" làm tân ngữ cho người, không thay cho vật.', 'Sai — "who" thay cho người, không cho vật.', 'Sai — "when" thay cho thời gian, không cho vật.']),
    Q('"That" có thể thay cho?', ['Chỉ vật', 'Chỉ người', 'Cả người và vật (trong mệnh đề xác định)', 'Không thay được'], 2, '"That" thay được cả người và vật, dùng trong mệnh đề xác định.', ['Sai — "that" không chỉ thay cho vật mà còn cho người.', 'Sai — "that" không chỉ thay cho người mà còn cho vật.', 'Đúng — "that" thay được cả người và vật, dùng trong mệnh đề xác định.', 'Sai — "that" thay được, chỉ là không dùng trong mệnh đề không xác định.']),
    Q('Hoàn thành: The man _____ lives next door is a doctor.', ['who', 'where (chỉ nơi chốn, không phải người)', 'which (thay cho vật, không cho người)', 'whose (chỉ quan hệ sở hữu, sai ngữ cảnh)'], 0, 'Thay cho "the man" (người, làm chủ ngữ) ⇒ "who".', ['Đúng — "the man" là người, làm chủ ngữ ⇒ "who".', 'Sai — "where" chỉ nơi chốn, không thay cho "the man".', 'Sai — "which" thay cho vật, không cho người.', 'Sai — "whose" chỉ quan hệ sở hữu, không hợp ở đây.']),
    Q('Hoàn thành: This is the book _____ I bought yesterday.', ['whose (chỉ sở hữu, không thay tân ngữ vật)', 'where (thay cho nơi chốn, không phải sách)', 'which/that', 'who (chỉ dùng cho người)'], 2, '"Book" là vật ⇒ "which" hoặc "that".', ['Sai — "whose" chỉ quan hệ sở hữu, không thay tân ngữ vật.', 'Sai — "where" thay cho nơi chốn, không phải sách.', 'Đúng — "book" là vật, làm tân ngữ ⇒ "which" hoặc "that".', 'Sai — "who" chỉ dùng cho người, không cho sách.']),
    Q('"Whose" dùng để thay cho?', ['Chỉ người', 'Chỉ nơi chốn', 'Chỉ vật', 'Sở hữu (người hoặc vật)'], 3, '"Whose" = "of which/of whom" ⇒ chỉ sở hữu.', ['Sai — "whose" chỉ sở hữu, không thay riêng cho người làm chủ ngữ.', 'Sai — nơi chốn dùng "where", không phải "whose".', 'Sai — "whose" chỉ sở hữu, không thay riêng cho vật.', 'Đúng — "whose" = of which/of whom, chỉ quan hệ sở hữu (người hoặc vật).']),
  ]),

  M(25, 'Relative Clauses — Non-defining (Mệnh đề quan hệ không xác định)', [
    Q('Mệnh đề quan hệ không xác định?', ['Không có dấu phẩy', 'Có dấu phẩy ngăn cách, bổ sung thông tin', 'Không dùng "which"', 'Bắt buộc cho ý nghĩa câu'], 1, 'Mệnh đề không xác định: có dấu phẩy + chỉ thêm thông tin phụ.', ['Sai — không có dấu phẩy là mệnh đề xác định, không phải không xác định.', 'Đúng — mệnh đề không xác định có dấu phẩy ngăn cách, chỉ bổ sung thông tin.', 'Sai — mệnh đề không xác định vẫn dùng "which" cho vật.', 'Sai — "bắt buộc cho ý nghĩa" là mệnh đề xác định; không xác định chỉ thêm thông tin.']),
    Q('Trong mệnh đề không xác định, KHÔNG dùng đại từ?', ['who (vẫn dùng được cho người sau dấu phẩy)', 'whose (vẫn dùng được chỉ sở hữu sau dấu phẩy)', 'that', 'which (vẫn dùng được cho vật sau dấu phẩy)'], 2, '"That" KHÔNG dùng trong mệnh đề không xác định.', ['Sai — "who" vẫn dùng được cho người trong mệnh đề không xác định.', 'Sai — "whose" vẫn dùng được chỉ sở hữu sau dấu phẩy.', 'Đúng — "that" KHÔNG dùng trong mệnh đề không xác định.', 'Sai — "which" vẫn dùng được cho vật trong mệnh đề không xác định.']),
    Q('Hoàn thành: My father, _____ is 60 years old, still works.', ['that (không dùng trong mệnh đề không xác định)', 'whose (chỉ quan hệ sở hữu, sai ngữ cảnh)', 'which (thay cho vật, không cho cha)', 'who'], 3, 'Mệnh đề không xác định cho "father" ⇒ "who" (không dùng "that").', ['Sai — "that" không dùng trong mệnh đề không xác định (có dấu phẩy).', 'Sai — "whose" chỉ quan hệ sở hữu, không hợp ở đây.', 'Sai — "which" thay cho vật, không thay cho "father" (người).', 'Đúng — "father" là người, mệnh đề không xác định ⇒ "who".']),
    Q('Đặt dấu câu đúng: "Hanoi which is the capital is beautiful."', ['Hanoi, which is the capital is beautiful.', 'Hanoi which, is the capital, is beautiful.', 'Hanoi, which is the capital, is beautiful.', 'Hanoi which is the capital, is beautiful.'], 2, 'Mệnh đề không xác định cần 2 dấu phẩy ngăn cách.', ['Sai — thiếu dấu phẩy đóng sau "capital"; cần đủ hai dấu phẩy.', 'Sai — dấu phẩy đặt sai vị trí (sau "which").', 'Đúng — mệnh đề không xác định cần hai dấu phẩy: Hanoi, which is the capital, is beautiful.', 'Sai — thiếu dấu phẩy mở trước "which".']),
    Q('"Mr. Smith, _____ son is my classmate, is a lawyer."?', ['which (thay cho vật, không chỉ sở hữu)', 'whom (tân ngữ chỉ người, không chỉ sở hữu)', 'who (chủ ngữ chỉ người, không chỉ sở hữu)', 'whose'], 3, 'Sở hữu (son của Mr. Smith) ⇒ "whose".', ['Sai — "which" thay cho vật, không chỉ quan hệ sở hữu.', 'Sai — "whom" làm tân ngữ chỉ người, không chỉ sở hữu.', 'Sai — "who" làm chủ ngữ chỉ người, không chỉ sở hữu.', 'Đúng — "son" thuộc về Mr. Smith (sở hữu) ⇒ "whose".']),
    Q('Khi nào dùng mệnh đề không xác định?', ['Không bao giờ', 'Khi cần xác định đối tượng', 'Khi không có danh từ riêng', 'Khi đối tượng đã được xác định rõ và mệnh đề chỉ bổ sung thông tin'], 3, 'Đối tượng đã rõ ⇒ chỉ thêm thông tin (không xác định).', ['Sai — mệnh đề không xác định vẫn được dùng thường xuyên.', 'Sai — "cần xác định đối tượng" là mệnh đề xác định, không phải không xác định.', 'Sai — không phụ thuộc danh từ riêng; phụ thuộc đối tượng đã rõ hay chưa.', 'Đúng — khi đối tượng đã rõ, mệnh đề chỉ bổ sung thông tin ⇒ không xác định.']),
  ]),

  M(26, 'English in the World — Vocabulary', [
    Q('"Native speaker" là?', ['Người học ngoại ngữ', 'Người bản xứ nói tiếng đó từ nhỏ', 'Học sinh giỏi', 'Giáo viên'], 1, '"Native speaker" = người nói ngôn ngữ đó như tiếng mẹ đẻ.', ['Sai — người học ngoại ngữ là "learner", không phải "native speaker".', 'Đúng — "native speaker" = người bản xứ nói ngôn ngữ đó như tiếng mẹ đẻ.', 'Sai — "học sinh giỏi" là "good student", không liên quan.', 'Sai — "giáo viên" là "teacher", không phải "native speaker".']),
    Q('"Fluent" có nghĩa?', ['Chậm rãi', 'Trôi chảy, lưu loát', 'Khó hiểu', 'Lưu loát (nhưng hay sai - sai phần "hay sai")'], 1, '"Fluent in English" = nói tiếng Anh lưu loát.', ['Sai — "chậm rãi" là "slow", trái với "fluent".', 'Đúng — "fluent" = trôi chảy, lưu loát (fluent in English).', 'Sai — "khó hiểu" là "unclear", trái với lưu loát.', 'Sai — "fluent" nghĩa lưu loát, không hàm ý "hay sai".']),
    Q('"Bilingual" nghĩa là?', ['Ba thứ tiếng', 'Một thứ tiếng', 'Nhiều thứ tiếng', 'Hai thứ tiếng'], 3, '"Bi-" = 2; "lingual" = liên quan đến ngôn ngữ.', ['Sai — ba thứ tiếng là "trilingual" (tri- = 3).', 'Sai — một thứ tiếng là "monolingual" (mono- = 1).', 'Sai — nhiều thứ tiếng là "multilingual" (multi- = nhiều).', 'Đúng — tiền tố "bi-" = 2 ⇒ "bilingual" = song ngữ.']),
    Q('"Multilingual" có nghĩa?', ['Không biết tiếng', 'Hai thứ tiếng', 'Đa ngôn ngữ', 'Một thứ tiếng'], 2, '"Multi-" = nhiều ⇒ đa ngôn ngữ.', ['Sai — "multilingual" là biết nhiều tiếng, không phải không biết tiếng.', 'Sai — hai thứ tiếng là "bilingual" (bi- = 2).', 'Đúng — tiền tố "multi-" = nhiều ⇒ đa ngôn ngữ.', 'Sai — một thứ tiếng là "monolingual" (mono- = 1).']),
    Q('"Dialect" là?', ['Tiếng nước ngoài', 'Tiếng phổ thông', 'Ngôn ngữ chính thức', 'Phương ngữ, tiếng địa phương'], 3, '"Dialect" = phương ngữ (vd: Northern dialect, Southern dialect).', ['Sai — tiếng nước ngoài là "foreign language", không phải "dialect".', 'Sai — tiếng phổ thông là "standard language", khác phương ngữ.', 'Sai — ngôn ngữ chính thức là "official language", không phải "dialect".', 'Đúng — "dialect" = phương ngữ, tiếng địa phương (Northern/Southern dialect).']),
    Q('"Accent" có nghĩa?', ['Từ vựng', 'Trọng âm câu', 'Giọng điệu, cách phát âm vùng miền', 'Ngữ pháp'], 2, '"Accent" = giọng (British accent, American accent…).', ['Sai — từ vựng là "vocabulary", không phải "accent".', 'Sai — "accent" cũng có nghĩa trọng âm từ, nhưng ở đây chỉ giọng vùng miền.', 'Đúng — "accent" = giọng, cách phát âm theo vùng (British/American accent).', 'Sai — ngữ pháp là "grammar", không phải "accent".']),
  ]),

  M(27, 'Reported speech — Comprehensive review', [
    Q('Khi tường thuật, thì hiện tại đơn lùi về?', ['Quá khứ hoàn thành', 'Không đổi', 'Quá khứ đơn', 'Hiện tại hoàn thành'], 2, 'Present simple → past simple khi tường thuật.', ['Sai — quá khứ hoàn thành là dạng lùi của present perfect/past simple, không phải present simple.', 'Sai — present simple phải lùi thì khi tường thuật (trừ sự thật hiển nhiên).', 'Đúng — present simple → past simple khi tường thuật.', 'Sai — hiện tại hoàn thành không phải dạng lùi của present simple.']),
    Q('"They said, \'We are studying.\'" → ?', ['They said we are studying.', 'They said we were studying.', 'They said they are studying.', 'They said they were studying.'], 3, 'Present continuous → past continuous; "we" → "they".', ['Sai — chưa lùi thì và chưa đổi "we" → "they".', 'Sai — đã lùi thì nhưng chưa đổi đại từ "we" → "they".', 'Sai — đã đổi đại từ nhưng chưa lùi thì "are" → "were".', 'Đúng — present continuous → past continuous; "we" → "they": they were studying.']),
    Q('"He said, \'I can swim.\'" → ?', ['He said he could swim.', 'He said I can swim.', 'He said he swims.', 'He said he can swim.'], 0, '"Can" → "could" khi lùi thì.', ['Đúng — "can" lùi thành "could"; "I" → "he".', 'Sai — chưa đổi "I" → "he" và chưa lùi "can" → "could".', 'Sai — "swims" làm mất nghĩa khả năng "can"; phải dùng "could swim".', 'Sai — chưa lùi thì: "can" phải thành "could".']),
    Q('Khi nào KHÔNG cần lùi thì trong câu tường thuật?', ['Luôn phải lùi thì', 'Khi câu dài', 'Không bao giờ lùi', 'Khi nói về sự thật hiển nhiên hoặc động từ giới thiệu ở hiện tại'], 3, 'Sự thật hiển nhiên hoặc "says/tells" ở hiện tại ⇒ không cần lùi thì.', ['Sai — có ngoại lệ: sự thật hiển nhiên hoặc động từ giới thiệu ở hiện tại.', 'Sai — độ dài câu không liên quan tới quy tắc lùi thì.', 'Sai — thường vẫn lùi thì khi động từ giới thiệu ở quá khứ.', 'Đúng — không lùi thì khi nói sự thật hiển nhiên hoặc "says/tells" ở hiện tại.']),
    Q('"She said, \'Don\'t worry!\'" → ?', ['She told us not to worry.', 'She told us don\'t worry.', 'She said us not worry.', 'She said not to worry.'], 0, 'Mệnh lệnh phủ định: told sb not to + V.', ['Đúng — mệnh lệnh phủ định: told + sb + not to + V.', 'Sai — phải dùng "not to worry", không phải "don\'t worry".', 'Sai — "say us" sai; dùng "told us not to worry".', 'Sai — thiếu tân ngữ; chuẩn là "told sb not to + V".']),
    Q('"He asked, \'What time is it?\'" → ?', ['He asked what time it is.', 'He asked what time is it.', 'He asked what time it was.', 'He asked what time was it.'], 2, 'Câu hỏi WH: bỏ đảo ngữ + lùi thì.', ['Sai — đã bỏ đảo ngữ nhưng chưa lùi thì: "is" → "was".', 'Sai — vẫn giữ đảo ngữ "is it"; câu tường thuật phải về trật tự bình thường.', 'Đúng — bỏ đảo ngữ và lùi thì: what time it was.', 'Sai — vẫn giữ đảo ngữ "was it"; phải về trật tự "it was".']),
  ]),

  M(28, 'Passive Voice — Comprehensive review', [
    Q('Bị động của "She is making a cake."?', ['A cake is being made.', 'A cake has been made.', 'A cake was made.', 'A cake is made.'], 0, 'Present continuous passive: is/are being + V3.', ['Đúng — hiện tại tiếp diễn bị động: is being made.', 'Sai — "has been made" là present perfect; gốc là hiện tại tiếp diễn.', 'Sai — "was made" là quá khứ đơn; gốc là hiện tại tiếp diễn.', 'Sai — "is made" là hiện tại đơn; thiếu "being" của tiếp diễn.']),
    Q('Bị động của "Will you finish the report?"', ['Will the report finished?', 'Will be the report finished?', 'Is the report finished?', 'Will the report be finished?'], 3, 'Future passive (câu hỏi): Will + S + be + V3?', ['Sai — thiếu "be"; phải là "Will the report be finished?".', 'Sai — sai trật tự; chuẩn là "Will + S + be + V3".', 'Sai — "Is...finished" là hiện tại đơn; gốc dùng "will".', 'Đúng — bị động tương lai dạng hỏi: Will the report be finished?']),
    Q('Bị động của "They must clean the room."?', ['The room must be cleaned.', 'The room must clean.', 'The room cleaned must be.', 'The room is must cleaned.'], 0, 'Modal passive: modal + be + V3.', ['Đúng — bị động với modal: modal + be + V3 (must be cleaned).', 'Sai — thiếu "be" và V3; "must clean" vẫn là chủ động.', 'Sai — sai trật tự từ hoàn toàn.', 'Sai — "is must cleaned" sai ngữ pháp; modal đi với "be + V3".']),
    Q('Bị động của "She had finished the work."?', ['The work has been finished.', 'The work had been finished.', 'The work had finished.', 'The work was finished.'], 1, 'Past perfect passive: had been + V3.', ['Sai — "has been" là present perfect; gốc "had finished" là past perfect.', 'Đúng — past perfect bị động: had been finished.', 'Sai — "had finished" vẫn là chủ động; bị động cần "had been finished".', 'Sai — "was finished" là quá khứ đơn; gốc là past perfect.']),
    Q('"This book _____ in 1990."?', ['was written', 'will be written', 'is written', 'has been written'], 0, 'Past simple passive với mốc thời gian rõ ràng "in 1990".', ['Đúng — mốc "in 1990" cần quá khứ đơn bị động: was written.', 'Sai — "will be written" là tương lai; "in 1990" là quá khứ.', 'Sai — "is written" là hiện tại đơn; mốc 1990 cần quá khứ.', 'Sai — present perfect không đi với mốc thời gian rõ ràng "in 1990".']),
    Q('Khi đổi sang bị động, cần lưu ý?', ['Bỏ chủ ngữ', 'Đổi thì', 'Bỏ động từ', 'Tân ngữ → chủ ngữ + chia "be" theo chủ ngữ mới + V3'], 3, 'Quy tắc: O → S; V → be + V3 (be chia theo S mới và thì gốc).', ['Sai — không bỏ chủ ngữ hẳn; chủ ngữ cũ thành "by + tác nhân" (có thể lược).', 'Sai — bị động GIỮ NGUYÊN thì gốc, chỉ đổi cấu trúc be + V3.', 'Sai — bị động vẫn có động từ chính (V3) cùng "be".', 'Đúng — tân ngữ → chủ ngữ, chia "be" theo chủ ngữ mới và thì gốc + V3.']),
  ]),

  M(29, 'Conditionals — Comprehensive review (Types 1, 2, 3)', [
    Q('Loại 1: If + present, then?', ['will + V', 'V (nguyên thể - thiếu "will")', 'would + V', 'would have + V3'], 0, 'Mệnh đề chính loại 1: will + V.', ['Đúng — vế chính loại 1: will + V.', 'Sai — chỉ V nguyên thể là loại 0; loại 1 cần "will + V".', 'Sai — "would + V" là vế chính loại 2.', 'Sai — "would have + V3" là vế chính loại 3.']),
    Q('Loại 2: If + past, then?', ['V (nguyên thể - thiếu "would")', 'will + V', 'would have + V3', 'would + V'], 3, 'Mệnh đề chính loại 2: would/could/might + V.', ['Sai — chỉ V nguyên thể là thiếu "would"; loại 2 cần "would + V".', 'Sai — "will + V" là vế chính loại 1.', 'Sai — "would have + V3" là vế chính loại 3.', 'Đúng — vế chính loại 2: would/could/might + V.']),
    Q('Loại 3: If + past perfect, then?', ['will + V', 'would have + V3', 'V (nguyên thể - thiếu "would have")', 'would + V'], 1, 'Mệnh đề chính loại 3: would/could/might have + V3.', ['Sai — "will + V" là vế chính loại 1.', 'Đúng — vế chính loại 3: would/could/might have + V3.', 'Sai — chỉ V nguyên thể là thiếu "would have" của loại 3.', 'Sai — "would + V" là vế chính loại 2, không phải loại 3.']),
    Q('"If I had a car, I would drive to work" thuộc loại?', ['3', '2', '0', '1'], 1, 'If + past simple ⇒ loại 2 (giả định hiện tại).', ['Sai — loại 3 dùng "If + had + V3"; ở đây "had a car" là past simple.', 'Đúng — "If + past simple, would + V" là loại 2 (giả định hiện tại).', 'Sai — loại 0 dùng "If + present, present"; ở đây có "would".', 'Sai — loại 1 dùng "If + present, will + V"; ở đây có "would".']),
    Q('"If she had studied, she would have passed" thuộc loại?', ['3', '1', '0', '2'], 0, 'If + past perfect ⇒ loại 3 (giả định quá khứ).', ['Đúng — "If + had + V3, would have + V3" là loại 3 (quá khứ trái thực tế).', 'Sai — loại 1 dùng "If + present, will + V".', 'Sai — loại 0 dùng "If + present, present".', 'Sai — loại 2 dùng "If + past simple, would + V", không có "would have".']),
    Q('Loại 0 dùng cho?', ['Lời khuyên', 'Tình huống không có thật', 'Sự thật hiển nhiên (If + present, S + V present)', 'Tình huống có thật'], 2, 'Loại 0: chân lý/sự thật: "If you heat water, it boils".', ['Sai — lời khuyên thường dùng loại 2 ("If I were you...").', 'Sai — tình huống không có thật là loại 2/3.', 'Đúng — loại 0 dùng cho sự thật hiển nhiên: If + present, S + present.', 'Sai — tình huống có thật ở tương lai là loại 1.']),
  ]),

  M(30, 'Tourism — Reading and Writing skills', [
    Q('"Itinerary" trong du lịch nghĩa là?', ['Vé máy bay', 'Lịch trình', 'Khách sạn', 'Hành lý'], 1, '"Itinerary" = lịch trình chuyến đi.', ['Sai — "vé máy bay" là "plane ticket", không phải "itinerary".', 'Đúng — "itinerary" = lịch trình chi tiết của chuyến đi.', 'Sai — "khách sạn" là "hotel", không phải "itinerary".', 'Sai — "hành lý" là "luggage", không liên quan.']),
    Q('"Tour guide" là?', ['Tài xế', 'Đầu bếp', 'Hướng dẫn viên du lịch', 'Khách du lịch'], 2, '"Tour guide" = hướng dẫn viên.', ['Sai — "tài xế" là "driver", không phải "tour guide".', 'Sai — "đầu bếp" là "chef/cook", không liên quan.', 'Đúng — "tour guide" = hướng dẫn viên du lịch.', 'Sai — "khách du lịch" là "tourist", người được hướng dẫn chứ không phải guide.']),
    Q('"Eco-tourism" là?', ['Du lịch sinh thái', 'Du lịch mua sắm', 'Du lịch ẩm thực', 'Du lịch tâm linh'], 0, '"Eco-tourism" = du lịch sinh thái, bảo vệ môi trường.', ['Đúng — "eco-" (ecological) ⇒ du lịch sinh thái, thân thiện môi trường.', 'Sai — du lịch mua sắm là "shopping tourism", không phải "eco".', 'Sai — du lịch ẩm thực là "food/culinary tourism".', 'Sai — du lịch tâm linh là "spiritual tourism", khác "eco-tourism".']),
    Q('Để viết bài giới thiệu địa điểm du lịch cần?', ['Chỉ giá cả', 'Nêu vị trí, đặc điểm, hoạt động có thể làm, lý do nên đến', 'Chỉ tả cảnh', 'Chỉ kể chuyện'], 1, 'Bài giới thiệu cần đầy đủ thông tin hữu ích cho du khách.', ['Sai — chỉ nêu giá cả là thiếu thông tin cần thiết cho du khách.', 'Đúng — cần nêu vị trí, đặc điểm, hoạt động và lý do nên đến.', 'Sai — chỉ tả cảnh thiếu thông tin thực tế (hoạt động, vị trí).', 'Sai — chỉ kể chuyện không cung cấp đủ thông tin du lịch.']),
    Q('"Souvenir" có nghĩa?', ['Đồ lưu niệm', 'Bản đồ', 'Vé (ticket - vật mua khi du lịch nhưng khác nghĩa)', 'Đặc sản (specialty - dễ nhầm với lưu niệm)'], 0, '"Souvenir" = đồ lưu niệm.', ['Đúng — "souvenir" = đồ lưu niệm (mua để kỷ niệm chuyến đi).', 'Sai — "bản đồ" là "map", không phải "souvenir".', 'Sai — "vé" là "ticket"; cũng mua khi du lịch nhưng khác nghĩa.', 'Sai — "đặc sản" là "specialty"; dễ nhầm nhưng không phải "souvenir".']),
    Q('"Off the beaten track" có nghĩa?', ['Những nơi ít người đến, không phải điểm du lịch quen thuộc', 'Đường ngắn nhất', 'Đi sai đường', 'Đi đường mòn'], 0, 'Thành ngữ: nơi ít người biết đến, đi xa khỏi tuyến du lịch chính.', ['Đúng — thành ngữ "off the beaten track" = nơi ít người đến, ngoài tuyến quen thuộc.', 'Sai — "đường ngắn nhất" là "shortest way", không phải nghĩa thành ngữ.', 'Sai — "đi sai đường" là "go the wrong way", khác nghĩa.', 'Sai — hiểu theo nghĩa đen "đường mòn" là sai; đây là thành ngữ chỉ nơi vắng.']),
  ]),

  M(31, 'Recipes and Eating Habits — Health and food', [
    Q('"Balanced diet" là?', ['Ăn nhiều', 'Chế độ ăn cân bằng dinh dưỡng', 'Ăn chay', 'Ăn kiêng giảm cân (diet plan - khác cân bằng)'], 1, '"Balanced diet" = chế độ ăn đầy đủ các nhóm chất.', ['Sai — "ăn nhiều" không phải "balanced"; cân bằng là đủ các nhóm chất.', 'Đúng — "balanced diet" = chế độ ăn cân bằng, đủ các nhóm dinh dưỡng.', 'Sai — "ăn chay" là "vegetarian diet", không đồng nghĩa cân bằng.', 'Sai — "ăn kiêng giảm cân" là "diet plan", khác với cân bằng dinh dưỡng.']),
    Q('"Nutrition" có nghĩa?', ['Thể thao', 'Bệnh tật', 'Năng lượng', 'Dinh dưỡng'], 3, '"Nutrition" = dinh dưỡng.', ['Sai — "thể thao" là "sport", không phải "nutrition".', 'Sai — "bệnh tật" là "illness/disease", không liên quan.', 'Sai — "năng lượng" là "energy"; nutrition là dinh dưỡng (rộng hơn).', 'Đúng — "nutrition" = dinh dưỡng (chất nuôi cơ thể).']),
    Q('"Junk food" là?', ['Đồ ăn nhanh, kém dinh dưỡng', 'Đồ ăn truyền thống', 'Đồ ăn chay', 'Thức ăn cao cấp'], 0, '"Junk food" = đồ ăn vặt, nhiều dầu mỡ, ít dinh dưỡng.', ['Đúng — "junk food" = đồ ăn vặt nhiều dầu mỡ, ít dinh dưỡng.', 'Sai — "đồ ăn truyền thống" là "traditional food", không phải junk food.', 'Sai — "đồ ăn chay" là "vegetarian food", khác junk food.', 'Sai — "thức ăn cao cấp" là "gourmet food", trái với junk food.']),
    Q('"Vegetarian" là?', ['Người ăn chay', 'Trẻ em', 'Người nấu ăn', 'Nông dân'], 0, '"Vegetarian" = người ăn chay.', ['Đúng — "vegetarian" = người ăn chay (không ăn thịt).', 'Sai — "trẻ em" là "children", không liên quan.', 'Sai — "người nấu ăn" là "cook/chef", không phải "vegetarian".', 'Sai — "nông dân" là "farmer", không phải "vegetarian".']),
    Q('Chọn từ phù hợp: You should eat more _____ for your health.', ['fruites', 'a fruit', 'fruit', 'fruits'], 2, '"Fruit" thường là danh từ không đếm được khi nói chung chung.', ['Sai — "fruites" sai chính tả; không có dạng này.', 'Sai — "a fruit" chỉ một quả cụ thể, không hợp ý "ăn nhiều hoa quả".', 'Đúng — nói chung chung "fruit" là danh từ không đếm được: eat more fruit.', 'Sai — "fruits" chỉ dùng khi nói nhiều LOẠI quả; nói chung dùng "fruit".']),
    Q('"Calorie" có nghĩa?', ['Mùi vị', 'Trọng lượng', 'Vitamin', 'Đơn vị năng lượng'], 3, '"Calorie" = đơn vị đo năng lượng thực phẩm.', ['Sai — "mùi vị" là "flavour/taste", không phải "calorie".', 'Sai — "trọng lượng" là "weight", không phải "calorie".', 'Sai — "vitamin" là một chất dinh dưỡng, không phải đơn vị năng lượng.', 'Đúng — "calorie" = đơn vị đo năng lượng trong thực phẩm.']),
  ]),

  M(32, 'Ôn tập tổng hợp ngữ pháp', [
    Q('Bị động: "People speak English all over the world."', ['English was spoken all over the world.', 'English speaks all over the world.', 'English is spoken all over the world.', 'English is being spoken.'], 2, 'Present simple passive: is + V3.', ['Sai — "was spoken" là quá khứ; gốc "speak" là hiện tại đơn.', 'Sai — "speaks" vẫn là chủ động; bị động cần "is + V3".', 'Đúng — hiện tại đơn bị động: is spoken.', 'Sai — "is being spoken" là hiện tại tiếp diễn; gốc là hiện tại đơn.']),
    Q('Tường thuật: "She said, \'I have just finished my homework.\'"', ['She said I had just finished.', 'She said she just finished.', 'She said she has just finished.', 'She said she had just finished her homework.'], 3, 'Present perfect → past perfect; pronouns đổi phù hợp.', ['Sai — chưa đổi đại từ "I" → "she".', 'Sai — "just finished" mất nghĩa hoàn thành; phải lùi thành past perfect.', 'Sai — chưa lùi thì: "has finished" phải thành "had finished".', 'Đúng — present perfect → past perfect: had just finished; "I/my" → "she/her".']),
    Q('Mệnh đề quan hệ: "The book _____ I read yesterday is interesting."', ['which/that', 'who (chỉ dùng cho người, không cho sách)', 'whose (chỉ quan hệ sở hữu, sai ngữ cảnh)', 'where (chỉ nơi chốn, không cho vật)'], 0, '"Book" là vật ⇒ which/that.', ['Đúng — "book" là vật, làm tân ngữ ⇒ which/that.', 'Sai — "who" chỉ dùng cho người, không cho sách.', 'Sai — "whose" chỉ quan hệ sở hữu, không hợp ngữ cảnh.', 'Sai — "where" thay cho nơi chốn, không cho vật.']),
    Q('Câu điều kiện: "If you _____ (study), you will pass."', ['had studied', 'will study', 'studied', 'study'], 3, 'Loại 1: If + present simple.', ['Sai — "had studied" thuộc loại 3; vế chính "will pass" báo hiệu loại 1.', 'Sai — KHÔNG dùng "will" trong mệnh đề "if" của loại 1.', 'Sai — "studied" quá khứ thuộc loại 2; ở đây là loại 1.', 'Đúng — loại 1: mệnh đề "if" dùng hiện tại đơn (study).']),
    Q('Câu ước: "I wish I _____ a doctor."', ['will be', 'were', 'have been', 'am (hiện tại đơn - sai thì sau "wish")'], 1, 'Wish + were (giả định hiện tại trái thực tế).', ['Sai — "will be" tương lai, không hợp ước hiện tại trái thực tế.', 'Đúng — wish + were cho mọi ngôi (giả định hiện tại trái thực tế).', 'Sai — "have been" hiện tại hoàn thành, không dùng sau "wish" ở đây.', 'Sai — "am" hiện tại đơn không dùng sau "wish"; phải lùi thành "were".']),
    Q('Used to: "He _____ smoke, but he quit."', ['used to', 'gets used to', 'use to', 'is used to'], 0, '"Used to + V" = đã từng.', ['Đúng — "used to + V" = đã từng (thói quen quá khứ): He used to smoke.', 'Sai — "get used to" = dần quen với, theo sau là noun/V-ing, khác nghĩa.', 'Sai — "use to" thiếu "-d"; khẳng định phải là "used to".', 'Sai — "be used to" = đã quen với, theo sau noun/V-ing, khác nghĩa "đã từng".']),
  ]),

  M(33, 'Đề ôn thi vào 10 — Đề số 1', [
    Q('Choose the best answer: "She has been studying English _____ 5 years."', ['since (đi với mốc thời gian cụ thể như 2020)', 'on (đi với ngày, không phải khoảng thời gian)', 'in (đi với tháng/năm, không phải khoảng)', 'for'], 3, '"For + khoảng thời gian"; "since + mốc thời gian".', ['Sai — "since" đi với mốc thời gian (since 2020), không với khoảng "5 years".', 'Sai — "on" đi với ngày cụ thể, không với khoảng thời gian.', 'Sai — "in" đi với tháng/năm/mùa, không với khoảng "5 years".', 'Đúng — "for + khoảng thời gian": for 5 years.']),
    Q('Find the error: "If I was you, I would tell the truth."', ['tell (động từ đúng cấu trúc loại 2)', 'truth (danh từ đúng, không có lỗi)', 'was', 'would (mệnh đề chính đúng loại 2)'], 2, 'Loại 2: nên dùng "were" cho mọi ngôi (trang trọng).', ['Sai — "tell" đúng (would + V nguyên thể), không phải lỗi.', 'Sai — "truth" là danh từ đúng, không có lỗi.', 'Đúng — lỗi ở "was"; loại 2 chuẩn mực dùng "were" cho mọi ngôi.', 'Sai — "would tell" đúng cấu trúc vế chính loại 2.']),
    Q('Choose the synonym of "fluent": "She speaks English fluently."', ['quickly', 'badly (trái nghĩa - kém, không trôi chảy)', 'smoothly', 'slowly'], 2, '"Fluent" ≈ "smooth" (trôi chảy).', ['Sai — "quickly" là nhanh, không đồng nghĩa "fluent" (trôi chảy).', 'Sai — "badly" là kém, trái nghĩa với "fluent".', 'Đúng — "smoothly" (trôi chảy) là từ gần nghĩa với "fluently".', 'Sai — "slowly" là chậm, trái với trôi chảy.']),
    Q('Bị động: "Someone has broken the window."', ['The window was broken.', 'The window broke.', 'The window has been broken.', 'The window is broken.'], 2, 'Present perfect passive: has been + V3.', ['Sai — "was broken" là quá khứ đơn; gốc "has broken" là present perfect.', 'Sai — "broke" vẫn chủ động quá khứ; gốc là present perfect.', 'Đúng — present perfect bị động: has been broken.', 'Sai — "is broken" là hiện tại đơn; gốc là present perfect.']),
    Q('Hoàn thành: "_____ raining, we went out."', ['In spite of', 'Although it was', 'Despite', 'Because it was'], 1, '"Although + clause"; "in spite of/despite + noun/gerund".', ['Sai — "in spite of" theo sau noun/gerund, không theo "raining" làm mệnh đề kiểu này.', 'Đúng — "Although + mệnh đề": Although it was raining, we went out.', 'Sai — "despite" theo sau noun/gerund, cần dạng "despite the rain".', 'Sai — "because" chỉ nguyên nhân, không hợp ý "trời mưa nhưng vẫn đi".']),
    Q('Word form: "She gave a _____ speech." (impress)', ['impress', 'impressive', 'impressively', 'impression'], 1, 'Tính từ trước danh từ "speech" ⇒ "impressive".', ['Sai — "impress" là động từ; trước danh từ cần tính từ.', 'Đúng — "impressive" (tính từ) bổ nghĩa cho danh từ "speech".', 'Sai — "impressively" là trạng từ; không đứng trước danh từ.', 'Sai — "impression" là danh từ; cần tính từ trước "speech".']),
  ]),

  M(34, 'Đề ôn thi vào 10 — Đề số 2 (Reading)', [
    Q('Đọc: "Da Lat is a beautiful city in the highlands of Vietnam. It is famous for flowers." Da Lat is famous for?', ['Markets', 'Flowers', 'Beaches', 'Snow (bài đọc không nhắc đến tuyết)'], 1, 'Câu thứ hai: "famous for flowers".', ['Sai — bài đọc không nhắc tới "markets" (chợ).', 'Đúng — câu thứ hai nêu rõ "famous for flowers" (hoa).', 'Sai — Đà Lạt ở cao nguyên, không có "beaches" (bãi biển).', 'Sai — bài đọc không nhắc đến "snow" (tuyết).']),
    Q('"Highlands" trong bài có nghĩa?', ['Bờ biển', 'Đồng bằng', 'Sa mạc', 'Cao nguyên'], 3, '"Highlands" = cao nguyên.', ['Sai — "bờ biển" là "coast", trái với vùng cao.', 'Sai — "đồng bằng" là "lowlands/plains", trái với "highlands".', 'Sai — "sa mạc" là "desert", không phải "highlands".', 'Đúng — "highlands" = cao nguyên, vùng đất cao.']),
    Q('Cụm "famous for" có thể thay bằng?', ['afraid of', 'good at', 'known for / renowned for', 'interested in'], 2, '"Famous for" = "known for" = "renowned for" (nổi tiếng vì).', ['Sai — "afraid of" = sợ, không liên quan tới nổi tiếng.', 'Sai — "good at" = giỏi về, khác nghĩa "famous for".', 'Đúng — "known for"/"renowned for" đồng nghĩa với "famous for".', 'Sai — "interested in" = quan tâm tới, không phải "nổi tiếng vì".']),
    Q('Đọc: "Vietnamese students study many subjects, including Math, Literature, and English." Số môn được nêu là?', ['4', '3', '2', '1'], 1, 'Liệt kê 3 môn: Math, Literature, English.', ['Sai — chỉ có 3 môn được liệt kê, không phải 4.', 'Đúng — liệt kê 3 môn: Math, Literature, English.', 'Sai — có 3 môn, không phải 2.', 'Sai — có 3 môn được nêu, không phải 1.']),
    Q('"Including" trong câu trên có nghĩa?', ['Trước hết', 'Bao gồm', 'Loại trừ', 'Sau đó'], 1, '"Including" = bao gồm.', ['Sai — "trước hết" là "firstly", không phải "including".', 'Đúng — "including" = bao gồm (dẫn ra ví dụ thuộc nhóm lớn hơn).', 'Sai — "loại trừ" là "excluding", trái nghĩa với "including".', 'Sai — "sau đó" là "then/after that", không phải "including".']),
    Q('Để tăng kỹ năng đọc hiểu, cần?', ['Tra từ điển mỗi từ', 'Đọc nhanh không hiểu', 'Đọc đa dạng, đoán nghĩa từ qua ngữ cảnh, không tra từ điển ngay', 'Bỏ qua nghĩa'], 2, 'Đoán nghĩa từ ngữ cảnh giúp đọc trôi chảy hơn.', ['Sai — tra từ điển mỗi từ làm gián đoạn, đọc chậm và mất mạch.', 'Sai — đọc nhanh mà không hiểu thì không cải thiện đọc hiểu.', 'Đúng — đọc đa dạng và đoán nghĩa qua ngữ cảnh giúp đọc trôi chảy hơn.', 'Sai — bỏ qua nghĩa thì không thể hiểu nội dung.']),
  ]),

  M(35, 'Đề ôn thi vào 10 — Đề số 3 (Writing & Grammar)', [
    Q('Rewrite: "It\'s a pity I don\'t have a car." → "I wish _____"', ['I will have a car.', 'I have a car.', 'I would have a car.', 'I had a car.'], 3, 'Wish + past simple cho giả định hiện tại.', ['Sai — "will have" tương lai, không hợp ước hiện tại trái thực tế.', 'Sai — sau "wish" phải lùi thì: "had", không phải "have".', 'Sai — "would have" dùng cho wish + would (mong thay đổi), không hợp ngữ cảnh.', 'Đúng — wish + past simple: I wish I had a car (giả định hiện tại trái thực tế).']),
    Q('Rewrite: "John is my friend. He lives in Hanoi." → "John, _____ lives in Hanoi, is my friend."', ['whom (làm tân ngữ, không phải chủ ngữ)', 'who', 'which (thay cho vật, không cho người)', 'whose (chỉ quan hệ sở hữu, sai ngữ cảnh)'], 1, 'Thay "he" (người, làm chủ ngữ) trong mệnh đề không xác định ⇒ "who".', ['Sai — "whom" làm tân ngữ; ở đây "he" làm chủ ngữ nên dùng "who".', 'Đúng — thay "he" (người, chủ ngữ) trong mệnh đề không xác định ⇒ "who".', 'Sai — "which" thay cho vật, không cho người.', 'Sai — "whose" chỉ quan hệ sở hữu, không hợp ngữ cảnh.']),
    Q('Đổi sang bị động: "They built this temple 200 years ago."', ['This temple will be built.', 'This temple was built 200 years ago.', 'This temple is built.', 'This temple has been built.'], 1, 'Past simple passive: was/were + V3.', ['Sai — "will be built" là tương lai; gốc "built ... ago" là quá khứ.', 'Đúng — quá khứ đơn bị động: was built 200 years ago.', 'Sai — "is built" là hiện tại đơn; gốc là quá khứ.', 'Sai — present perfect không đi với "200 years ago" (mốc quá khứ rõ ràng).']),
    Q('Hoàn thành: "If she had told me earlier, I _____ him."', ['would have helped', 'would help', 'helped', 'will help'], 0, 'Loại 3: would have + V3.', ['Đúng — vế "if" là "had told" (loại 3) ⇒ vế chính "would have + V3".', 'Sai — "would help" là vế chính loại 2; ở đây là loại 3.', 'Sai — "helped" quá khứ đơn không phải vế chính loại 3.', 'Sai — "will help" là vế chính loại 1; ở đây là loại 3.']),
    Q('Word form: "Education plays an important role in _____ society." (modern)', ['modernity', 'modern', 'modernly', 'modernize'], 1, 'Trước danh từ "society" cần tính từ ⇒ "modern".', ['Sai — "modernity" là danh từ; trước "society" cần tính từ.', 'Đúng — "modern" (tính từ) bổ nghĩa cho danh từ "society".', 'Sai — "modernly" là trạng từ; không đứng trước danh từ.', 'Sai — "modernize" là động từ; cần tính từ trước "society".']),
    Q('Để viết một bài luận tốt, cần?', ['Dùng từ khó', 'Dịch từ tiếng Việt', 'Có dàn ý rõ (mở-thân-kết), dùng linking words, đa dạng cấu trúc', 'Viết dài'], 2, 'Tổ chức ý + ngôn ngữ chính xác + cấu trúc đa dạng = bài luận tốt.', ['Sai — dùng từ khó không bằng dùng từ chính xác và mạch lạc.', 'Sai — dịch word-by-word từ tiếng Việt dễ sai cấu trúc tiếng Anh.', 'Đúng — dàn ý rõ (mở-thân-kết), linking words và cấu trúc đa dạng làm nên bài luận tốt.', 'Sai — viết dài không đồng nghĩa với viết hay; chất lượng quan trọng hơn độ dài.']),
  ]),
];

export const S9TA_SCENARIOS = indexBy(S9TA_WEEKS);
